(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["4-1"] = [{"a": [1], "v": 3, "p": 1072, "ev": 3, "ep": 1081, "sid": 1273, "t": "وقوله: ﴿خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ﴾⟪4:1⟫ ذكر عامة المفسرين أنه عنى بالنفس\nآدم، وزوجها: حواء.\nوذكر بعضهم أنه عنى بالنفس الروح المذكورة في قوله - صلى الله عليه وسلم -: \"إن الله خلق الأوواح قبل الأجسام بكذا سنة\".\nوعنى بزوجها البدن.\nوقيل: عنى به التركيب، وإلى\n⟦3:1073⟧\nنحوه أشار بقوله: ﴿وَمِن كُلِّ شَيۡءٍ خَلَقۡنَا زَوۡجَيۡنِ﴾⟪51:49⟫.\nوقوله: ﴿سُبۡحَٰنَ ٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا يَعۡلَمُونَ﴾⟪36:36⟫، ولا يصح معنى ذلك في النبات إلا على\nمعنى التركيب، ونبه بذكر الزوجين والأزواج في الأشياء على\nأنها لا تنفك من ترتيب ما، وأن الواحد في الحقيقة ليس إلا هو\nتعالى، قال: وعلى هذا نبه بقوله: ﴿وَٱلشَّفۡعِ وَٱلۡوَتۡرِ﴾⟪89:3⟫، وقال\nمعنى الشفع: الخلق، والوتر: الخالق.\nوهذا القول في الآية\n⟦3:1074⟧\nوإن كان متجها، فأهل الأثر على\"ما تقدم.\nإن قيل: على أي وجه خلق زوجها منها أخذ جزءا فجعل زوجها؟\nقيل: قال بعضهم: الشيئان قد يقال لأحدهما:\nهو من الآخر. إذا كان من عنصره وأصله.\nكقولك: هذا القميص من قميصك.\nوقد يقال ذلك إذا كانا مشتركين في صفة، نحو ﴿بَعۡضُكُم مِّنۢ بَعۡضٖۚ﴾.\nوقال بعضهم: أخذ جزءا من آدم، وجعل منه حواء.\nوعلى ذلك روي: \"خلقت حواء من ضلع من أضلاع \"،\n⟦3:1075⟧\nوقال بعضهم: نبه بقوله: ﴿وَخَلَقَ مِنۡهَا زَوۡجَهَا﴾⟪4:1⟫ أن المرأة بعض من الرجل.\nتنبيها على نقصانها وكماله، وآنجه نبه - صلى الله عليه وسلم - بقوله ذلك أنها مخلوقة خلقة معوجة، لا ينتفع بها إلا كذلك، فلا يهمنك تنقيتها، وعلى\nذلك قال - صلى الله عليه وسلم -: \"إن المرأة خلقت من ضلع، وإنك إن أردت أن تقيمها كسرتها، وإن تركتها وفيها عوج استمتعت بها \".\nوبهذا النظر قيل: أخس صفات الرجل الشح والجبن، وهما أشرف\nصفات المرأة.\nإن قيل: ما وجه عطف الأرحام على الله، والتقوى في الحقيقة\nمن الله ومن عذابه، لا من الرحم، وقد كان الوجه أن يقال:\n⟦3:1076⟧\nاتقوا الله في الأرحام أو للأرحام؟\nقيل: أجيب عن ذلك بأوجه:\nالأول: أنه لما كان يقال: اتق الله، أي اتق عقوبة عصيانه.\nواتق ذنبك، أي عقوبة ذنبك، قال ههنا: (اتقوا الله)، أي اتقوا\nعقوبته على طريق الجملة.\nثم قال: والأرحام. أي عقوبته في قطع الأرحام.\nوخصها بالذكر تعظيما لأمرها، وكأنه قيل: اتقوا\nعقوبات الله عامة، وعقوبته في قطع الأرحام خاصة، وذلك\nلتعظيمه أمر الرحم.\nوالوجه الثاني: أن تقديره: اتقوا الله في الرحم، لكن حذف\nالجار، وأقيم حرف العطف مقامه، كقولهم: يدك والسكين.\nأي احفظ يدك من السكين.\n⟦3:1077⟧\nوالوجه الثالث: أن تقديره: اتقوا الله وقوا الأرحام.\nفأحدهما متقى، والآخر موقى، نحو قولهم: أعور عينك والحجر.\nأي: ق عينك، واتق الحجر.\nإن قيل: ما وجه إعادة التقوى وعطف أحدهما على الآخر؟\nقيل: إنه أمر في الأول بالتقوى أمرا عاما، ولهذا قال: (ربكم)\nتنبيها على أفضاله، وإحالتهم على ما لا يمكن لأحد إنكاره.\nولما قصد الحث على الحافظة على الرحم قذم ذكر الموجد باللفظ الذي\nفيه التنبيه على القدرة التامة.\nإن قيل: ما وجه ذكر (تساءلون به)؟\n⟦3:1078⟧\nقيل: زيادة في الترغيب في تقواه، وتنبيها على كون تعظيمه\nمنغرسا في قلوبنا، حتى إنا إليه نفزع إذا سألنا، ونبه أنا كما نقول:\nأسألك بالله. نقول: أسألك بالرحم، وتقدير الكلام: اتقوا الله\nالذي تسألون به، والأرحام التي تسألون بها، لكن نبه بوصف\nالأول على وصف الثاني، وللقصد إلى هذا المعنى قرأ من قرأ:\n\" الأرحام \" بالخفض.\nإن قيل: ما فائدة قوله: ﴿خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ﴾⟪4:1⟫؟\nقيل: تنبيها على وجوب مواصلة بعضنا بعضا، لكوننا من ذات واحدة، وأنا\n⟦3:1079⟧\nكبنيان يشد بعضه بعضا، وأما بخفض قوله: (والأرحام) فقد\nقيل: فيه ضعف من حيث الإعراب، ومن حيث المعنى (1)؛\nأما من حيث الإعراب فلأن ضمير المجرور لما كان على حرف واحد قائم\nمقام التنوين، والتنوين لا يصح أن يعطف عليه، كذلك الضمير\nالمجرور، وأيضا فلأن كل ما يعطف عليه يصح أن يعطف هو.\nولما كان ضمير المجرور لم يصح أن يعطف عليه، وبيان ذلك أن\nللمرفوع والمنصوب ضميرا منفصلا، نحو: هو وهما وإيا. فيصح\nأن يقال: رأيتك وزيدا، أو رأيت زيدا وإياك، وأتيتني وزيد.\nوأتاني زيد وأنت، ولم يكن للمجرور ضمير منفصل يقع موقع\nالمتصل فيعطف به، فلم يجز لذلك أن يعطف عليه أيضا.\n⟦3:1080⟧\nوأما من حيث المعنى: فإن إعادة الأمر بالتقوى فلاقتران\nذكرها بصفة تحث سامعها على استعمال التقوى، كقولك: اتق\nالله الذي تخافه، واتق الله الذي بيده الخير.\nفهذه الصفات هي التي تحسن التكرير.\nفإذا نصبت الأرحام ففيه هذا المعنى.\nوإذا جررته لم يكن في ضمنه من التحذير ما فيه إذا نصبته.\nوإنما قال: ﴿وَخَلَقَ مِنۡهَا﴾⟪4:1⟫ ردا إلى لفظ النفس، وكل اسم جنس، لفظه\n⟦3:1081⟧\nمخالف لمعناه أي، التذكير والتأنيث، فلك اعتبار اللفظ طورا\nوالمعنى طورا، نحو: حمامة ونفس، وإذا كان علما نحو:\nطلحة. أو صفة نحو: علامة ونسابة، فليس إلا اعتبار المعنى\nدون اللفظ.\nوالرقيب. قال مجاهد: هو الحفيظ، وقال ابن زيد: عليم).\nوكلاهما صحيح، فحافظ الشيء يقتضي أن يكون عالما\nبه ليمكنه أن يحفظه، وبين بقوله: ﴿كَانَ عَلَيۡكُمۡ رَقِيبٗا﴾⟪4:1⟫ أنه قبل\nأن خلقكم وأوجدكم كان مراعيا لكم، تنبيها أنه لا يخفى عليه\nأمركم في كل حال."}, {"a": [2], "v": 3, "p": 1082, "ev": 3, "ep": 1085, "sid": 1283, "t": "قوله تعالى: (وآتوا اليتامى أموالهم ولا تتبدلوا الخبيث بالطيب ولا تأكلوا أموالهم إلى أموالكم إنه كان حوبا كبيرا (2)\nالخبيث والطيب: عبارتان عن الحرام والحلال، أي تدفعوا\nإليهم شيئا هو طيب لكم، وتأخذوا من مالهم ما هو خبيث لكم.\nطلبا للربح. هذا قول الضحاك والسدي.\nوقيل: لا تتبدلوا الهزيل بالسمين.\nوقيل: الطيب مقدار ما أبيح تناوله من مال\n⟦3:1083⟧\nاليتيم، والخبيث ما لم يبح منه، وهو المشار إليه بقوله: ﴿وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ﴾⟪4:6⟫.\nوكل هذه الأقوال إشارات إلى ما يقتضيه عموم الخبيث والطيب.\nوالحوب: الإثم لكونه مزجورا عنه، من قولهم: حاب حوبا\nوحوبا وحيابة، والأصل فيه حوب لزجر الإبل، وتحوب\nنحو تأثم، وإيتاء اليتامى أموالهم، قيل: دفعها إليهم بعد\nالبلوغ، وسماهم حينئذ يتامى استصحابا للحالة المتقدمة،\n⟦3:1084⟧\nويكون ذلك كقوله: ﴿حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ﴾⟪4:6⟫ وقيل: هو إنفاقها عليهم، ودفعها شيئا\nبمعد شيء على قدر الحاجة .\nوالضمير في قوله: (إنه) قيل: للأكل. وقيل: للتبدل.\nوقيل: للأموال، لكن اعتبر المعنى\n⟦3:1085⟧\nلما كان المال والأموال في هذا الموضع سواء، كقول الشاعر:\n. . . . . . . . . . . . . . . . . . . . . . . .، فإن الحوادث أودى بها\nلما كان معنى الحوادث والحدثان واحدا."}, {"a": [3], "v": 3, "p": 1085, "ev": 3, "ep": 1095, "sid": 1286, "t": "قوله تعالى: (وإن خفتم ألا تقسطوا في اليتامى فانكحوا ما طاب لكم من النساء مثنى وثلاث ورباع فإن خفتم ألا تعدلوا فواحدة أو ما ملكت أيمانكم ذلك أدنى ألا تعولوا (3)\nالعول: الخروج عن حد الاستقامة، والعول في الفريضة خروج\nعن حد السهام المسماة، والعويل: الصياح الخارج عن حد الاستقامة\nفي الكلام، وذلك نحو الألفاظ التي يتحراها المصاب.\nوعولت عليه ملت نحوه بالاعتماد، والمعول على بناء الآلة، كأنه آلة العول.\n⟦3:1086⟧\nوالآية تؤولت على وجهين:\nأحدهما: قيل: إن الرجل قبل الإسلام إذا مات كان وليه يسير في أيتامه سيرة غير قاصدة، ويأكل أمو الهم إسرافا وبدارا، وكانوا يسيرون في يتامى النساء\nخاصة بأقبح سيرة، فإنها متى كانت اليتيمة ذات مال وجمال\nتزوجوا بها بأقل من مهرها، ثم لم يحسنوا إليها، وإن كان أحدهم\nلا يرغب فيها عضلها عن النكاح، طمعا في مالها، فلما جاء\nالإسلام نهوا عن ذلك بهذه الآية.\nوقوله: ﴿وَإِنۡ خِفۡتُمۡ﴾⟪4:3⟫ أي إن خفتم أن لا تستعملوا العدالة -\nأي إذا تزوجتم بهن فتزوجوا من غيرهن. وإلى هذا ذهب ابن\nعباس وعائشة.\nوالثاني: أنهم يتحرجون في أموال اليتامى، لما\n⟦3:1087⟧\nعظم الله تعالى من أمرهم في نحو قوله: ﴿وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ﴾ الآية.\nولم يكونوا يتحرجون من التزوج بعدد من النساء، فقال\nتعالى إن تحرجتم عن تناول مال اليتيم خشية أن لا تقسطوا.\nفتحرجوا النساء أن لا تعدلوا بينهن، وانكحوا مقدار ما يمكنكم\nالوفاء بحقوقهن.\nوقيل: معناه إن خفتم أن لا تقسطوا في حفظ أموال اليتامى.\nوأن تجوروا في الإنفاق على نسائكم.\nفانكحوا عددا مخصوصا لا يحوجكم إلى أن تقسطوا.\nإن قيل: فما معنى ذكر هذه الأعداد إن كان الأمر على ما وصفت؟\nوهلا قيل: فانكحوا ماطاب لكم من النساء سواهن؟\n⟦3:1088⟧\nقيل: يجوز للحكيم إذا سئل عن حكم أن يجيب عنه، ويقرن إليه ما\nعلم أن بالسائل حاجة إليه. فلما سئل عن ذلك، وكان فيهم من لا\nيبالي أن يتزوج بالعدد الكثير من النساء، بين العدد الذي لا يجوز أن\nيتعداه الإنسان في وقت واحد، ولذلك أحيلوا على هذه الآية لما\nاستفتوا في يتامى النساء، فقال تعالى: ﴿وَيَسۡتَفۡتُونَكَ فِي ٱلنِّسَآءِۖ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِيهِنَّ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ﴾⟪4:127⟫ الآية.\nوقد اختلف في العدد الذي يجوز أن ينتهى إليه في النكاح.\nفمذهب عامة الفقهاء أنه لا يجوز مجاوزة الأربع، ومذهب بعض\nالشيعة أنه يجوز بلا عدد كالسراري.\nوقال: الآية ليست بتوقيف، بل هي إباحة: كقولك: تناول ما أحببت واحدا واثنين وثلاثة، وأن تخصيص بعض مقتضى العموم على طريق\nالتبيين لا يقتضي الاقتصار عليه، وذهب بعضهم ممن لا يعرف\nشرط الكلام إلى أن المباح منهن تسع، وقال: الواو تقتضي\nالجمع، فصار كقولك: اثنين وثلاثا وأربعا، وذلك تسع.\nوأكد ذلك بأن النبي - صلى الله عليه وسلم - مات عن تسغ نسوة.\nقال: وغير منكر أن\n⟦3:1089⟧\nيذكر عدد واحد بلفظين، كما قال: ﴿ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ﴾⟪2:196⟫.\nوهذا فاسد، أما أولا: فإن العدول عن ذكر الشيء بلفظة\nواحدة إلى لفظين، إما أن يكون لغرض نحو ﴿ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ﴾⟪2:196⟫، لما خالف بين حكميهما أورده بلفظين.\nأو يكون ذلك للعي والاستدراك عن نسيان، وكلام الله تعالى منزه\nعن ذلك، ومنهم من رد إلى واحدة، لتأويل انتزعه من\nالآيتين: إحداهما هذه، والأخرى قوله: ﴿وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ بَيۡنَ ٱلنِّسَآءِ﴾⟪4:129⟫ الآية. قال: فبين أنكم لا تستطيعون\nتحري العدالة في النساء، وقال ههنا: ﴿فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً﴾⟪4:3⟫.\nفكأنه قال: انكحوا واحدة إن لم تستطيعوا أن تعدلوا.\n⟦3:1090⟧\nفقد ثبت أن لا تستطيعوا، فإذا، فانحكوا واحدة، وهذا القائل\nخفي عليه الفرق بين العدلين، فإن العدل في تلك الآية ترك ميل\nالقلب، وذلك مرفوع عن الإنسان، لقوله تعالى: ﴿لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ﴾⟪2:286⟫.\nوقوله: ﴿فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً﴾⟪4:3⟫ عنى به العدل الذي\nهو حق القسم والنفقة، ولهذا قال: ﴿فَإِنۡ خِفۡتُمۡ﴾⟪4:3⟫ فإن الخوف\nيقال فيما فيه رجاء ما، ولهذا لا يقال: خفت أن لا أقدر\nعلى بلوغ السماء أو نسف الجبل.\nوهذه الأقوال المتقدمة يبطلها ما روي أنه لما نزلت هذه الآية\nكانت تحت قيس بن الحارث ثمان نسوة، فقال له - صلى الله عليه وسلم -: \"خل سبيل أربع \".\n⟦3:1091⟧\nوكذا قال لابن مسعود الثقفي، وكان قد أسلم وتحته تسع\nنسوة، واستدل أهل الظاهر بالآية على وجوب النكاح.\nواستدل بها بعض الفقهاء على أنه غير واجب، وبيان هذا أن\n⟦3:1092⟧\nما في قوله: ﴿فَٱنكِحُواْ مَا طَابَ لَكُم﴾⟪4:3⟫ إما أن يكون عبارة عن\nالمنكوحة، أو عن الزمان، أو العدد. فلا يصح الأول.\nلأن (ما) لا يعبر به عن أعيان العقلاء مجردا، ولا عن العدد، لأنه محال أن يعني نكاح العدد، وإن عنى المعدود فالكلام راجع إلى أن يكون عبارة\nعن العقلاء، فيجب أن يكون عبارة عن الزمان، فكأنه قال: اعقدوا\nوقت ما يطيب لكم، والمخالف يوجبه طاب لنا أو لم يطب.\n⟦3:1093⟧\nفإن قيل: معناه ما تاقت أنفسكم إليه، قيل: إن عنى ما تاقت\nنفسه إلى العقد فليس ذلك مذهبا لأحد، وإن عنى المخالف: ما\nتاقت نفسه إلى الجماع، فلم يجر للجماع ذكر.\nوقد تقدم الكلام في العول، فقول من قال:\nذلك أدنى أن لا تجاوزوا ما فرض الله.\nوقول من قال: أن لا تميلوا، يرجعان إلى أصل واحد.\nوقول الشافعي معناه: أن لا يكثر عيالكم.\nوقد ذهب إلى هذا التأويل\n⟦3:1094⟧\nزيد بن أسلم، وأجازه الأصمعي، وابن الأعرابي.\nومنه قيل: فلان يعول عشرة، وقال ابن داود: غلط\nالشافعي، لأن صاحب الإماء في العيال كصاحب الأزواج.\n⟦3:1095⟧\nوابن داود لم يتصور ما قاله الشافعي، وذاك أنه لم يرد إلا ما أراد\nغيره من حقيقة المعنى، وإنما تحرى اشتقاق اللفظ، ولم يرد بالعيال\nالأولاد، وإنما أراد النساء، فقد يسمى كل من تسمونه العيال، وإن\nلم يكن أولادا، وأراد تعالى إن خفتم أن يكثر نساؤكم، فتحتاجوا\nإلى تفقدهن بأمور تقصرون عنها ، ولا يكون في مراعاتها إقساط.\nوهذا راجع إلى ما ذهب إليه الآخرون."}, {"a": [4], "v": 3, "p": 1095, "ev": 3, "ep": 1099, "sid": 1296, "t": "قوله تعالى: (وآتوا النساء صدقاتهن نحلة فإن طبن لكم عن شيء منه نفسا فكلوه هنيئا مريئا (4)\nفالنحلة: العطية التي لا يطلب بها عوض، وأصله عندي من النحل.\nفكأن نحلته: أعطيته عطية النحل، وذلك ما قصده الحكماء من\nوصف النحل في أنه لا يضر بشيء، وينفع أعظم نفع، وكأنه إلى\nذلك أشار بقوله: ﴿وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ﴾⟪16:68⟫ الآية،\n⟦3:1096⟧\nوالنحلة أخص من الهبة، إذ كل هبة نحلة، وليس كل نحلة هبة.\nوسمي الصداق بها من حيث لا يجب في مقابلته أكثر من تمتع دون\nعوض مالي. وقول قتادة وابن زيد: النحلة: الفريضة.\nفنظر منهم إلى حكم الآية، لا إلى موضوع اللفظ والاشتقاق.\nواقتضت إيجاب إيتائهن الصداق.\nثم حكمه وقدره قبل الدخول وبعده، وقبل التسمية وبعدها.\nفمأخوذ من غير الآية.\nودل بقوله تعالى: ﴿فَإِن طِبۡنَ﴾⟪4:4⟫ أن لا يتحرج الإنسان من قبول\nهبتها عن طيب نفس منها بها، ودلت الآية على أنه يجوز لها أن\nتهب صداقها إذا كانت بالغة، خلافا لما قال مالك: إن ذلك إلى وليها.\n⟦3:1097⟧\nوللأوزاعي حيث قال: لا يجوز لها حتى تلد.\nأو يحول عليها الحول في بيت زوجها.\nولليث بن سعد حيث قال: لا يجوز عتق ذات الزوج ولا هبتها.\nإلا في اليسير من غير إذن زوجها.\nوذكر عن شريح أن رجلا أتى بينة أن امرأته\n⟦3:1098⟧\nأبرأته من صداقها عن طيب نفس، وأنكرت المرأة ذلك.\nفقال شريح: هل رأيتم المال وقد دفع إليها؟ فقالوا: لا.\nفقال: لو طابت نفسها لم ترجع فيه، فلم يجزه.\nإن قيل: لم قال: ﴿فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا﴾⟪4:4⟫ فأفرد\nوقال في الأخرى: (بالأخسرين أعمالا) فجمع؟\nقيل: التمييز على ثلاثة أضرب:\nالأول: أن يدل ما قبله على عدد فلا يجمع، نحو: عشرون درهما.\nوالثاني: أن يشتبه، فلابد من جمع إذا أريد الجمع نحو قولهم: أفره القوم عبيدا.\nوالثالث: أن يستوي الواحد والجمع لكونه معلوما منها المعنى على حد، نحو\nقولهم: فلان أحسن القوم عينا، لأنه يعلم أن القوم لم يشتركوا\n⟦3:1099⟧\nفي عين واحدة، والآية على هذا فلا يحتاج فيها إلى الجمع.\nوالضمير في (منه) راجع إلى مصدر (فأتوهن)."}, {"a": [5], "v": 3, "p": 1099, "ev": 3, "ep": 1103, "sid": 1300, "t": "قوله تعالى: (ولا تؤتوا السفهاء أموالكم التي جعل الله لكم قياما وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا (5)\nالسفهاء قيل: النساء،\n⟦3:1100⟧\nوقيل: الصبيان، ومنهم من اعتبر ذلك في كل من لم يكن حصيفا\nفي تدبير المال، ومنهم من اعتبر ذلك مع الحصافة في الدين.\nوكل واحد أشار إلى بعض من يتناوله الاسم على سبيل المثال.\nفمعلوم أنه لا يصح صرفها إلى النساء مفردات، لقوله: (وارزقوهم)\nوالنهي عن إيتائهن المال على سبيل تفويض تدبير الأموال إليهن.\nوقيل: على سبيل تمليكهن على وجه التمكين، لا على نهي الإعطاء\nبقدر ما يحتاجون إليه.\nوقال ابن جبير: معناه لا تعطوهم أموالهم.\nوإضافته إلى المخاطبين على اعتبار الجنس، نحو قوله: ﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ﴾⟪4:29⟫، ونظر بعضهم نظرا آخر، فقال: عنى\n⟦3:1101⟧\nبالسفهاء الوارثين، الذين يعلم من حالهم أن يتسفهوا في استعمال\nما تناله أيديهم، فنهى عن جميع المال الذي يرثه السفهاء، ونبه\nبقوله: ﴿ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا﴾⟪4:5⟫ على الغرض الذي فصله الحكماء\nمن فائدة المال الموصل به إلى السعادة الحقيقة، بل قد أبانه النبي\n- صلى الله عليه وسلم - بأوجز لفظ، فقال:\n\"من طلب الدنيا استعفافا عن المسألة، وسعيا على أهله.\nوتعطفا على جاره، بعثه الله ووجهه كالقمر ليلة البدر.\nومن طلبها حلالا، مكاثرا، مفاخرا، مرائيا، لقي الله وهو\nعليه غضبان \".\nوالقيام يكون مصدرا واسما، والقوام لا يكون إلا اسما.\n⟦3:1102⟧\nإن قيل: لم قال: (فيها) ولم يقل: منها. مع كون ذلك أظهر؟\nقيل: قد ذكر بعضهم أن فيه تنبيها على ما قاله - صلى الله عليه وسلم -: \"ابتغوا في أموال اليتامى، لا تاكلها الزكاة\".\nوأن المستحب أن يكون الإنفاق عليها من فضلاتها المكتسبة.\nوالقول المعروف متضمن للأمر بتأديبهم وإرشادهم ووعدهم الجميل، الذي ذكره ابن جريج، وقال: هو أن يقال له: إن رشدت مكناك من مالك،\n⟦3:1103⟧\nوفيه المنع عن قهرهم، وإليه ذهب مجاهد استدلالا بقوله تعالى:\n﴿فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ﴾⟪93:9⟫"}, {"a": [6], "v": 3, "p": 1103, "ev": 3, "ep": 1108, "sid": 1304, "t": "قوله تعالى: (وابتلوا اليتامى حتى إذا بلغوا النكاح فإن آنستم منهم رشدا فادفعوا إليهم أموالهم ولا تأكلوها إسرافا وبدارا أن يكبروا ومن كان غنيا فليستعفف ومن كان فقيرا فليأكل بالمعروف فإذا دفعتم إليهم أموالهم فأشهدوا عليهم وكفى بالله حسيبا (6)\nالإيناس فيما رئي مرة بعد أخرى فأنس به.\nوقد فسره ابن عباس بالمعرفة.\nوالخليل فسره بالإحساس. والرشد،\n⟦3:1104⟧\nقال الحسن وقتادة: وهو الصلاح في الدين والإصلاح للمال.\nوقال مجاهد: هو الإصلاح للمال فقط، وأمر تعالى بدفع المال إلى اليتامى\nبعد البلوغ وإيناس الرشد منهم، وبعد الابتلاء، وجعل ذلك كله\nشرطا في تسليم المال إليه، ومعلوم من الآية أن من دفع إليه المال، ثم\nفقد منه الرشد أن يعاد الحجر عليه، لأن الغرض بذلك حفظ\nماله، فلا فرق بين أن يكون المعنى الموجب للحجر ابتداء أو انتهاء.\n⟦3:1105⟧\nوالآية تقتضي أن كل من حصل في يده مال لغيره لزمه حفظه له\nكمال المفقود، ومال الفقراء في بيت المال، واللقطة في يد الملتقط.\nوالابتلاء المراد في الآية، قيل: هو حال الصغر بأن يدفع إليه\nقليل من المال، فيرى حفظه له وتصرفه فيه.\nوقيل: هو بأن يجرب في أمور أخر.\nوقيل: هو أن يختبر بعد البلوغ، وسفاهم يتامى\nاستصحابا للحالة المتقدمة، وقوله: ﴿وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا﴾⟪4:6⟫\nأي متجاوزين حد القصد المباح لكم، ومبادرة أن يكبروا، فيمنعوا\nأموالهم).\nوقوله: ﴿وَمَن كَانَ غَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ﴾⟪4:6⟫.\nقيل: لا يتناول منه شيئا.\n⟦3:1106⟧\n﴿وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ﴾⟪4:6⟫ من مال نفسه لا من مال اليتيم، لئلا يحتاج إلى مد اليد إلى ماله.\nوقيل: فليأكل بالمعروف من مال اليتيم.\nوقيل: ذلك منسوخ بقوله: ﴿إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا﴾⟪4:10⟫ الآية، وقال الأصم: فليأكل من مال اليتيم قرضا.\nوإليه ذهب عمر، فقال: إني في مال الله كوالي اليتيم، إن استغنيت استعففت، وإن افتقرت أكلت بالمعروف،\n⟦3:1107⟧\nفإذا أيسرت قضيت. وقيل: يتناول الفقير\nالأقل من قدر حاجته، أو قدر أجرة مثله.\nوقيل: ليس لوالي اليتيم أن يتناول ذلك، وإن تولى إصلاحه إلا بأمر من له الأمر، وإليه ينصرف ما روي أن رجلا أتى النبي - صلى الله عليه وسلم - فقال: إن في حجري يتيما أفآكل من ماله؟\nقال: \"نعم، ما لم تق مالك بماله، أو تتخذ منه ذخرا\"،\n⟦3:1108⟧\nوإلى نحوه صرف قوله: ﴿وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ﴾.\nوالأمر بالإشهاد عليهم عند دفع أموالهم إليهم على سبيل الإيجاب.\nوقوله: ﴿وَكَفَىٰ بِٱللَّهِ حَسِيبٗا﴾⟪4:6⟫، تنبيه منه تعالى أنه رقيب عليهم.\nيعلم أسرارهم، وأنه يحاسبهم على ما يكون منهم، فليس للولي أن يخون، ولا لليتيم أن يدعي ما ليس له."}, {"a": [7], "v": 3, "p": 1108, "ev": 3, "ep": 1111, "sid": 1309, "t": "قوله تعالى: (للرجال نصيب مما ترك الوالدان والأقربون وللنساء نصيب مما ترك الوالدان والأقربون مما قل منه أو كثر نصيبا مفروضا (7)\n⟦3:1109⟧\nالمفروض: المقطوع بإيجابه، والفرض الحز في شية\nالقوس، والفرضة مقطع الماء، إما اعتبارا بقطع الماء أو قطع\nالخصومة فيه.\nوبعض الفقهاء فرق بين الفرض والواجب، فجعل الفرض أخص.\nوقال: إنه يقتضي فارضا، والواجب لا يقتضيه.\nقال: ولذلك يقال: ثواب المطيعين واجب على الله.\nولا يقال: فرض عليه، وروي أن العرب كانوا يورثون الذكور\nدون الإناث، وقيل: كانوا لا يورثون إلا من طعن من الرماح\nدون المستضعفين من الولدان، قيل: إن أوس بن ثابت مات\n⟦3:1110⟧\nوخلف بنات وابني عم، فعمدا إلى المال وأخذاه.\nفجاءت امرأة أوس ببناته إلى النبي - صلى الله عليه وسلم - وأعلمته ذلك، فأخبرها أن لا شيء لها ولا لهن. فأنزل الله تعالى الآية، فبعث النبي - صلى الله عليه وسلم - إلى ابني عم أوس، فأمرهما أن لا يخرجا من المال شيئا، ثم نزلت آية الميراث، فقسم المال عليهم، فاستدل بهذه الآية أصحاب الإمام\nأبي حنيفة على توريث ذوي الأرحام.\nوقالوا: الأخوال والخالات وأولاد البنات من الأقربين.\nوتعلق بذلك أيضا من ورث الإخوة مع الجد، وكذلك من ورث العامل والمماليك.\n⟦3:1111⟧\nوقوله: ﴿نَصِيبٗا مَّفۡرُوضٗا﴾⟪4:7⟫ يقتضي خلاف من ورث ذوي الأرحام.\nإذ ليس لأحد منهم نصيب مفروض.\nفإن قيل: لم أعيد ذكر النصيب؟\nقيل: لما أراد أن يبين كون نصيبهم مفروضا أعاد الموصوف معه.\nليستبين أن المفروض هو النصيب لا غير."}, {"a": [8], "v": 3, "p": 1111, "ev": 3, "ep": 1113, "sid": 1312, "t": "قوله تعالى: (وإذا حضر القسمة أولو القربى واليتامى والمساكين فارزقوهم منه وقولوا لهم قولا معروفا (8)\nأراد بالقسمة المقسوم، ولذلك: (فارزقوهم منه) رد إلى المعنى.\nواختلف في الآية على أقوال: الأول: أنه عنى من ليس بوارث\nمن أولي القربى، وذلك على الاستحباب، فإما أن يعطوا،\n⟦3:1112⟧\nأو يقال لهم قول معروف، وقيل: يجمع لهم بين الأمرين.\nوالثاني: قال مجاهد: هو واجب، لكن يعطون على قدر ما تطيب\nبه نفس الورثة، إذ كانوا وارثين.\nقال الحسن والنخعي: أدركنا الناس وهم يقسمون على الأقارب واليتامى والمساكين من الورق والفضة، فإذا صاروا إلى الأرضين والرقيق ونحوها، قالوا لهم قولا معروفا، أي قالوا لهم: بورك فيكم.\nالثالث: أن أولي القربى ضربان: وارث يعطى، وغير وارث.\nفيقال له قول معروف.\nالرابع: يعطى الحاضر البالغ، ويتحرى في أمر\n⟦3:1113⟧\nالغائب والصغير قول معروف أي مصلحة.\nالخامس. قال زيد من أسلم: هذا شيء أمر به الموصي في الوقت\nالذي يوصي، واستدل في ذلك بقوله بهد هذه الآية: ﴿وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةٗ﴾⟪4:9⟫ الآية.\nالسادس: أن ذلك كان في الورثة واجبا، فنسخته آية الميراث.\nوالصحيح أنه ليس بمنسوخ، وعلى ذلك قوله تعالى: ﴿وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ﴾⟪17:26⟫، ثم قال: ﴿وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةٖ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلٗا مَّيۡسُورٗا﴾⟪17:28⟫."}, {"a": [9], "v": 3, "p": 1114, "ev": 3, "ep": 1117, "sid": 1315, "t": "قوله تعالى: (وليخش الذين لو تركوا من خلفهم ذرية ضعافا خافوا عليهم فليتقوا الله وليقولوا قولا سديدا (9)\nأصل السداد: إزالة الاختلال، يقال: سددت الخرق. إذا ردمته.\nوالسهم إذا قومته، والفقر إذا أزلته، والسداد ما يسد به، والسداد\nيقال في معنى الفاعل، وفي معنى المفعول، ورجل سديد متردد\nبين المعنيين، فإنه مسدد من قبل متبوعه، ومسدد لتابعه، وفي\nالآية أقوال: الأول: أنه نهي للحاضرين عند الموصي أن يأمروه\nبما لا يجوز الوصية به.\nوالثاني: أنه نهي لهم أن يأمروه بترك الوصية.\n⟦3:1115⟧\nالثالث: ما قد روي عن ابن عباس أن ذلك وارد في\nالحث على حفظ مال اليتيم، وأن عليهم أن يعملوا فيه بمثل ما\nيحبون في ذريتهم بعد موتهم.\nالرابع: أنه نهي للموصي أن يوصي بما لا يجوز.\nوكل هذه الأقوال يصح أن تكون مرادة بالآية، لأنه واجب أن لا يوصي بأكثر من الثلث، وواجب على من يحضره أن يحثه على ذلك، وأن لا يوصي بأكثر من الثلث، وأن لا يخل بالوصية.\n⟦3:1116⟧\nإن قيل: لم قال: ﴿وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ﴾⟪4:9⟫، ثم قال:\n﴿فَلۡيَتَّقُواْ ٱللَّهَ﴾⟪4:9⟫؟ وهل بين الخشية والتقوى فرق؟\nقيل: الخشية الاحتراز من الشيء بمقتضى العلم.\nولذلك وصف به العلماء في قوله تعالى:\n﴿إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ﴾⟪35:28⟫.\nوالتقوى جعل العبد نفسه في وقاية مما يخشاه، ولذلك قال: ﴿يَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ﴾⟪2:21⟫ إلى قوله: ﴿لَعَلَّكُمۡ تَتَّقُونَ﴾.\nفالخشية مبدأ التقوى، والتقوى غاية الخشية.\nفأمر الله تعالى بمراعاة المبدأ والنهاية، إذ لا ينفع الأول دون الثاني.\nولا يحصل الثاني من\n⟦3:1117⟧\nدون الأول، ثم أمر تعالى مع ذلك بتحري القول السديد، وذلك\nمتناول لكل قول مأمور به، وقول من قال: هو تلقين المحتضر\nالشهادة، وقول من قال: هو ترك الرفث في تولي القسمة.\nوقول من قال: هو الصدق في الشهادة - داخل في عموم الآية."}, {"a": [10], "v": 3, "p": 1117, "ev": 3, "ep": 1120, "sid": 1318, "t": "قوله تعالى: (إن الذين يأكلون أموال اليتامى ظلما إنما يأكلون في بطونهم نارا وسيصلون سعيرا (10)\nالصلا: النار، وصلي فلان بها وصليته: أدنيته منها.\nوصليت اللحم: شويته.\nفقوله: (وسيصلون) من صلي، ويصلون من أصليت.\nنحو ﴿فَسَوۡفَ نُصۡلِيهِ نَارٗاۚ﴾⟪4:30⟫، والسعير: المسعور.\nواستعرت النار والحرب تشبيها بذلك، وهذه الآية مؤكدة لما قبلها من\n⟦3:1118⟧\nالأمو بالخشية والتقوى، ووعيد لمن تعدى، وذكر الأكل لكونه\nأكثر ما يراد له المال.\nوقيل: إنه لما نزلت هذه الآية تحرج الناس من طعام اليتيم\nحتى أنزل الله تعالى: ﴿وَإِن تُخَالِطُوهُمۡ فَإِخۡوَٰنُكُمۡۚ وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ﴾⟪2:220⟫، وليس هذا ناسخا للأول، كما ظنه قوم، لأنه ليس في قوله: ﴿وَإِن تُخَالِطُوهُمۡ﴾⟪2:220⟫ إباحة لأكل مال اليتيم ظلما، فتكون هذه ناسخة لها، في\n⟦3:1119⟧\nقوله: ﴿يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ﴾⟪4:10⟫ وجهان:\nأحدهما: أن ذلك تشبيه، إذ كان ذلك مؤديا إليه .\nكقول النبي - صلى الله عليه وسلم -:\n\"يتهافتون في النار تهافت الجراد\".\nوكقول الشاعر:\nإذا صب ما في الوطب فاعلم بأنه. . . دم الشيخ فاشرب من دم الشيخ أو دعا\nفسمى اللبن دما لكونه بدلا منه.\nوالثاني ما روي أن النار تجعل في بطنه يوم القيامة.\nوالقولان صحيحان وسيان، فإنه من\n⟦3:1120⟧\nكان حاله في الآخرة هذه، هو الذي حاله في الدنيا ما قاله الأولون."}, {"a": [11], "v": 3, "p": 1120, "ev": 3, "ep": 1130, "sid": 1321, "t": "قوله تعالى: (يوصيكم الله في أولادكم للذكر مثل حظ الأنثيين فإن كن نساء فوق اثنتين فلهن ثلثا ما ترك وإن كانت واحدة فلها النصف ولأبويه لكل واحد منهما السدس مما ترك إن كان له ولد فإن لم يكن له ولد وورثه أبواه فلأمه الثلث فإن كان له إخوة فلأمه السدس من بعد وصية يوصي بها أو دين آباؤكم وأبناؤكم لا تدرون أيهم أقرب لكم نفعا فريضة من الله إن الله كان عليما حكيما (11)\nالوصية: تقال فيما كان حتما، نحو قوله\n⟦3:1121⟧\nتعالى: ﴿وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ﴾ ثم قال:\n﴿ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ﴾.\nوقال ابن عباس: كان المال للولد في الجاهلية.\nوالوصية للوالدين والأقربين، فنسخه هذه الآية.\nواستدل بما روي أنه لما نزلت هذه الآية قال - صلى الله عليه وسلم -:\n\"إن الله قد أعطى كل ذي حق حقه، فلا وصية لوارث \".\nوقال غيره: الآية غير ناسخة، بل هي تفسير لقوله: ﴿لِّلرِّجَالِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ﴾⟪4:7⟫.\nواختلف: هل يدخل ولد الابن في\n⟦3:1122⟧\nإطلاق الولد؟ فمنهم من قال: يدخل فيه، لقولهم: أولاد آدم.\nولأن جميع ما علق بالولد من الأحكام فابن الابن داخل فيه، نحو\n﴿حُرِّمَتۡ عَلَيۡكُمۡ﴾، ثم قال: ﴿وَحَلَٰٓئِلُ أَبۡنَآئِكُمُ﴾⟪4:23⟫.\nوقوله: ﴿أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ﴾⟪24:31⟫ ولا خلاف أن حكم ولد\nالابن إذا لم يكن ولد صلب حكمه، وقد استثني من ظاهر\nقوله: ﴿لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ﴾⟪4:11⟫\nالكافر والمملوك والقاتل وأهل ملتين، إلا عند معاذ.\nفإنه يورث المسلم من الكافر.\nوقوله: ﴿فَإِن كُنَّ نِسَآءٗ فَوۡقَ ٱثۡنَتَيۡنِ﴾⟪4:11⟫ فإن الله جعل للبنات إذا\nكن فوق اثنتين الثلثين، وللواحدة النصف، ولم يذكر فرض\n⟦3:1123⟧\nالبنتين، قال ابن عباس: حكمهما حكم الواحدة.\nوقال سائر الفقهاء: حكمهما حكم ما فوقهما.\nثم اختلف من أي وجه صار حكم الاثنتين حكم ما فوقهما؟\nفقال بعضهم: إن ذلك أجري مجرى الثلاث بالقياس، لأنه به أشبه.\nوقال بعضهم: بل اللفظ اقتضى ذلك، وهو الصحيح.\nوبيان ذلك أنه قال: ﴿لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ﴾⟪4:11⟫.\nولا فرق بين أن يقال ذلك أو يقال: للأثثيين مثل حظ الذكر.\nوقد ثبت أن حظ الذكر إذا كان مع أنثى الثلثان.\nفاقتضى ذلك أن فرض الأنثيين الثلثان، فصار ذلك\nمدلولا عليه بفحوى الكلام دون الصريح، وفرض الواحدة\nوما زاد على البنتين فبالصريح، قال: ويقوي ذلك أن القسمة\nالعددية ضربان: مركب ومفرد، وقد ذكر حكم المركب بقوله:\n﴿فَإِن كُنَّ نِسَآءٗ﴾⟪4:11⟫، وحكم المفرد بقوله: ﴿وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ﴾⟪4:11⟫، والاثنان بدء المركب من الأعداد، فيجب أن يكون حكمه ملحقا به.\nويدل على ذلك ما قاله في آخر السورة قوله:\n⟦3:1124⟧\n﴿وَلَهُۥٓ أُخۡتٞ فَلَهَا نِصۡفُ مَا تَرَكَۚ﴾⟪4:176⟫، ثم قال: ﴿فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ﴾⟪4:176⟫، فجعل حظ البنتين الثلثين، ولم يبين حكم ما زاد عليهما.\nوبين في فرض البنات حكم ما فوق الابنتين، ليعلم من نطق\nكل واحد من الاثنين حكم المسكوت عنه في الأخرى.\nفإن قيل: متى جعل حكم الاثنتين حكم الثلاث فصاعدا\nسقط فائدة قوله: ﴿فَوۡقَ ٱثۡنَتَيۡنِ﴾⟪4:11⟫؟\nقيل: مثل هذا راجع إلى المخالف، لأنه يقال له: متى جعلت حكم الاثنتين حكم الواحدة سقط فائدة قوله: ﴿وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ﴾⟪4:11⟫؟\nوجوابه في ذلك جوابنا عما سأل، على أن ذكر ذلك على التنزيل الذي نزلناه لابد من ذكره، لأنه بين حكم الاثنتين بقوله: ﴿لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ﴾⟪4:11⟫، ثم بين حكم ما فوق الاثنتين، ثم حكم الواحدة.\nومن قال: تقدير الكلام: فإن كن نساء اثنتين، وإن قوله (فوق)\nزائد كقوله: ﴿فَٱضۡرِبُواْ فَوۡقَ ٱلۡأَعۡنَاقِ﴾⟪8:12⟫، لأنه أراد فاضربوا\nالأعناق، فغير موافق في ادعاء الزيادة في الموضعين، وغير موافق\nفي تأويل الابنتين، وبهلام الله تعالى منزه عن ذكر لفظ خلوة عن\nقصد معنى صحيح ، إذكان ذلك لغوا، تعالى الله عنه.\n⟦3:1125⟧\nإن قيل: لم ذكر فرض البنت إذا انفردت، ولم يذكر الابن\nعلى الانفراد؟\nقيل: لأن العرب كانوا يورثون البنين دون البنات، فاحتيج إلى تبيين ذلك، دون ما بقوا على ما كانوا عليه.\nوقوله: ﴿وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ﴾⟪4:11⟫ ظاهره يقتضي أن يكون\nللأب السدس مع الولد: ذكرا كان أو أنثى، كما أن فرض الأم\nكذلك، لأنه لا خلاف متى كان الولد بنتا لا يستحق أكثر من\nالنصف، لقوله: ﴿وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ﴾⟪4:11⟫ فيعطى\nالأبوان السدسين بحكم النص، وبقي سدس يناوله الأب بما\nنبه عليه بقوله: (وورثه ؤأبواه فلأئه الثلمشأ)، لما جمع نصيبهما.\nثم أفرد نصيب الأم على أن الباقي للأب.\nوقوله: ﴿وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ﴾⟪4:11⟫ فالإخوة ههنا\nمتناولة للإخوة والأخوات، لكن غلب التذكير، وبين تعالى ميراث\n⟦3:1126⟧\nالأم عند وجود الإخوة، والظاهر يقتضي أن الأم تستحق السدس\nإذا كانت للميت ثلاثة إخوة فصاعدا.\nوأما إذا كان أخوان فالظاهر لا يقتضي ذلك.\nوقال ابن عباس: إن الآية لا تتناول ذلك، فلم\nتحجب الأم عن الثلث بدون الثلاثة، ولا بالأخوات\nمنفردات، وخالفه سائر الصحابة، وحجبوها باثنين من\nالإخوة والأخوات، كما حجبوها بأكثر من ذلك.\nوقالوا: المراد بالأخوة حصول من له الإخوة دون العدد.\nودون الذكورية والأنوثية.\nولا خلاف أن الواحد لا يحجب الأم.\n⟦3:1127⟧\nوقوله: ﴿مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ﴾⟪4:11⟫\nقال أمير المؤمنين علي عليه السلام:\nالوصية مقدمة في اللفظ مؤخرة في المعنى.\nفإن مراعاة الذين قبل مراعاة الوصية، وإنما قيل (أو دين)\n⟦3:1128⟧\nولم يقل أو، دين، ليقتضيهما مجموعين ومفردين.\nوقوله: ﴿ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ﴾⟪4:11⟫، قيل: القصد بذلك أن المنفعة بهما\nمتفاوتة، فإن المنفعة بالآباء في الصغر، وبالأبناء في الكبر.\nوقيل: معناه تحروا ما أمرتم، ولا تعتبروا نفع الولد والوالد، فإن\nذلك يختلف عند اعتبار الآحاد.\nوقيل: معناه لا يدري أحدكم أهو أقرب وفاة، فينتفع ولده بماله.\nأم الولد أقرب وفاة فينتفع\n⟦3:1129⟧\nالوالدان بماله، وإلى هذا المعنى أشار الشاعر:\nما علم ذي ولد أيثكله. . . أم الولد اليتيم ؟\nوهذا الذكر في الآية كالاستطراد، والقصد به يجب أن يتحرى\nفي ماله الوجه الذي جعل له المال، فلا يمنع ذا حق من حقه، شفقة\nعلى ورثته، ولا يضعه في غير حقه \"تفاديا من انتقال ماله إلى ورثته.\nبل يجب أن يتحرى القصد في ذلك، فليس يدري عواقب الأمور.\nوجملة ذلك أن في الآية حثا على تفويض الأمر إلى الله، والرضا\nبحكمه، وقوله: ﴿فَرِيضَةٗ مِّنَ ٱللَّهِۗ﴾⟪4:11⟫ اسم موضوع موضع\nالمصدر، نحو قوله: ﴿كِتَٰبٗا مُّؤَجَّلٗاۗ﴾⟪3:145⟫، و ﴿كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ﴾⟪4:24⟫.\nومعناه قسمة مقدرة، وقيل: معناه حتما\n⟦3:1130⟧\nلازما، وكلا المعنيين يقتضيه لفظ الفريضة."}, {"a": [12], "v": 3, "p": 1130, "ev": 3, "ep": 1137, "sid": 1331, "t": "قوله تعالى: (ولكم نصف ما ترك أزواجكم إن لم يكن لهن ولد فإن كان لهن ولد فلكم الربع مما تركن من بعد وصية يوصين بها أو دين ولهن الربع مما تركتم إن لم يكن لكم ولد فإن كان لكم ولد فلهن الثمن مما تركتم من بعد وصية توصون بها أو دين وإن كان رجل يورث كلالة أو امرأة وله أخ أو أخت فلكل واحد منهما السدس فإن كانوا أكثر من ذلك فهم شركاء في الثلث من بعد وصية يوصى بها أو دين غير مضار وصية من الله والله عليم حليم (12)\nالكلالة: اسم لمن عدا الولد والوالد.\nوقال ابن عباس: اسم لمن عدا الولد وورث الإخوة مع الأب، وإليه كان\n⟦3:1131⟧\nيذهب ابن عمر ثم رجع عنه، ويدل أن الأب ليس بكلالة\nقول الشاعر:\nوإن أبا المرء أحمى له. . . ومولى الكلالة لا يغضب\nوروي أن النبي - صلى الله عليه وسلم - سئل عن ذلك، فقال:\n\"من مات وليس له ولد ولا والد فورثته كلالة\".\nوقال بعضهم: الكلالة من لا ولد له ولا والد.\nفجعله اسم الميت، وكلا القولين صحيح،\n⟦3:1132⟧\nفإن الكلالة مصدر، وهو اسم للمعنى الذي يجمعهما.\nفسمي به الوارث تارة والموروث تارة، وتسميتها بذلك إما\nلأن النسب قد لحق به من طرفيه، أو لأنه كل عن اللحوق\nبه، وذلك أن الانتساب ضربان:\nأحدهما: بالعمق كنسبة الأب والابن.\nوالثاني: بالعرض كنسبة الأخ والعم.\nوقال قطرب: الكلالة لمن عدا الأبوين والأخ\n⟦3:1133⟧\nوليس بشيء، وقال بعضهم: هو اسم لكل وارث.\nلقول الشاعر:\n. . . وللكلالة ما يسيم\nولم يقصد الشاعر ما ظنه هذا القائل، فإنه إنما خص الكلالة\nليزهد الإنسان في جمع المال، لأن تخليف المال لهم أشد من\nتركه الأولاد، وإذا قرئ يورث فكلالة مفعول، وإذا قرئ\n⟦3:1134⟧\nيورث فحال للميت.\nفرض الله تعالى للزوج النصف إذا لم يكن للميتة ولد، دخل بها\nأو لم يدخل، وجعل له الربع إذا كان لها ولد، سواء كان منه أو من\nغيره، وفرض الربع للزوجات إذا لم يكن للميت ولد، والثمن إذا\nكان له ولد، وأجمعوا أن ولد الابن يقوم مقام ولد الصلب في حجب\nالزوجين، إلا حكاية عن بعض المتقدمين، وأجمعوا أن للزوجة\nالواحدة إذا انفردت ما للزوجات إذا اجتمعن، وذهبت طائفة إلى\nأن من لا يرث من مملوك وقاتل يحجب الزوجين والأم، لأن اسم\nالولد يتناولهم، كما يحجب الإخوة الأم مع الولد، وإن لم يرثوا،\n⟦3:1135⟧\nوقوله: ﴿وَلَهُۥٓ أَخٌ أَوۡ أُخۡتٞ﴾⟪4:12⟫، جعل لواحدهم السدس.\nوأشرك بين جماعتهم في الثلت، ولم يفضل ذكرهم على\nأنثاهم، وعنى بذلك ولد الأم بدليل قوله في إخوة الأب\nوالأم، ﴿وَإِن كَانُوٓاْ إِخۡوَةٗ رِّجَالٗا وَنِسَآءٗ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ﴾⟪4:176⟫\nوروي أن سعد بن مالك قرأ: وله أخ أو أخت من أم.\n⟦3:1136⟧\nقال بعضهم: لعله فسر الإخوة بذلك، فظن السامع أنه\nقرأه في القرآن، كما روي عن عمر: فامضوا إلى ذكر الله على\nمعنى التفسير للسعي، فظن أنه قرآن.\nوقوله: ﴿فَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ﴾⟪4:12⟫ فذلك لتغليب المذكر.\nوقرىء يوصي بها، فإذا قرئ يوصى بالفتح فصفة الوصية، وإذا قرئ بكسر الصاد احتمل أن تكون صفة للوصية وأن تكون حالا للموصي\nوقرأ الحسن: غير مضار وصية بالإضافة.\nوالباقون بالتنوين، ونصب وصية على المصدر أو على المفعول به.\nوالإضرار أن يقر بمال لأجنبي، ردا\n⟦3:1137⟧\nللميراث، أو يبيع ماله أو شيئا منه محابيا فيه، أو يهب، أو يعتق.\nأو يوصي لوارثه قصدا للإضرار بغيره."}, {"a": [13], "v": 3, "p": 1137, "ev": 3, "ep": 1139, "sid": 1338, "t": "قوله تعالى: (تلك حدود الله ومن يطع الله ورسوله يدخله جنات تجري من تحتها الأنهار خالدين فيها وذلك الفوز العظيم (13)\nبين بذكر الحد أن ذلك يؤدي بالإنسان إلى العصيان.\nونبه بقوله: ﴿وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ﴾⟪4:13⟫ على وجوب مراعاة ما بينه تعالى في الكتاب من أحكام المواريث، وما بينه - صلى الله عليه وسلم - من نحو قوله: \" لا وصية لوارث \"، وقوله: \"لك الثلث والثلث. . . \".\nقال ابن عباس: الضرار\n⟦3:1138⟧\nفي الوصية من الكبائر، ثم قرأ ﴿تِلۡكَ حُدُودُ ٱللَّهِۚ﴾⟪4:13⟫.\nوقد روي ذلك عن النبي - صلى الله عليه وسلم -\nوقال - صلى الله عليه وسلم -:\n\"إن أحدكم يعمل بعمل أهل الجنة سبعين سنة، فإذا أوصي حاف في وصيته، فيختم له بسوء عمله \".\nووصف الفوز بالعظيم اعتبارا بفوز الدنيا\n⟦3:1139⟧\nالموصوف بقوله تعالى: ﴿قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ﴾⟪4:77⟫ والقليل والصغير\nفي وصفها متقاربان."}, {"a": [14], "v": 3, "p": 1139, "ev": 3, "ep": 1139, "sid": 1340, "t": "قوله تعالى: (ومن يعص الله ورسوله ويتعد حدوده يدخله نارا خالدا فيها وله عذاب مهين (14)\nكما وصف في مراعاة الحدود ثواب مراعيها وصف في\nتضييعها عقاب متعديها، وأطلق القول فيهما ليكون عاما في\nذلك وفي غيره من الحدود التي بينها، وذكر في العذاب الهوان.\nكما ذكر في غيره الخزي لما عرف من عادة كثير من الناس أن\nتقل مبالاتهم بالشدائد ما لم يضامها، الهوان حتى قالوا: المنية\nولا الدنية، والنار ولا العار.\nفبين أنه يجمع لهم الأمران."}, {"a": [15], "v": 3, "p": 1139, "ev": 3, "ep": 1143, "sid": 1340, "t": "قوله تعالى: (واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل الله لهن سبيلا (15)\n⟦3:1140⟧\nفائدة الإضافة في قوله: ﴿مِن نِّسَآئِكُمۡ﴾⟪4:15⟫ تنبيه على الحرائر.\nوقيل: تنبيه على المحصنات دون الأبكار.\nوقيل: على المزوجات أبكارا كن أو ثيبات.\nقال ابن عباس في هذه الآية، وفي قوله: (واللذان يأتيانها منكم) إن الزانيين كانا يؤذيان بالتعيير والتعزير، والمرأة كانت تحبس في البيت إلى أن أنزل الله قوله: ﴿ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ﴾⟪24:2⟫ الآية.\nوقيل: المراد بالآيتين البكران.\nوقوله: ﴿أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلٗا﴾⟪4:15⟫:\n\"البكر بالبكر جلد مائة وتغريب عام، والثيب بالثيب جلد مائة\n⟦3:1141⟧\nوالرجم \"، وهذا مما استدل به من ادعى جواز نسخ القرآن\nبالسنة، ومن أنكر ذلك فله من ذلك أجوبة:\nأحدها: أن هذا كان حكما مقيدا بوقت، لقوله: ﴿أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلٗا﴾⟪4:15⟫، وتقديره: أمسكوهن إلى أن يتبين لكم حكمهن، فصار ذلك\nبالكتاب معلوما، وإنما حظ السنة فيه بيان قدر الزمان، الذي\nوقته الكتاب مجملا.\nوالثاني: أن الأذى كان في الأبكار اللاتي لم يتزوجن.\nوالحبس في التزوجات منهن قبل الدخول، بدلالة\n⟦3:1142⟧\nقوله: ﴿مِن نِّسَآئِكُمۡ﴾⟪4:15⟫، ثم نسخ حكم الحبس والأذى في\nالأبكار بآية الجلد، وأما الرجم فقد أخذ حكمه عن السنة.\nولهذا قال علي عليه السلام حيث جلد محصنا ورجمه، فسئل عن\nذلك؟ فقال: \"أجلده بكتاب الله، وأرجمه بسنة رسوله - صلى الله عليه وسلم -، فدل أنه لم يفهم من سنة النبي نسخ الآية.\nوالثالث: أن حكم النسخ وقع بقرآن، قد رفع تلاوته، وبقي حكمه.\nوهو ما روي عن عمر رضي الله عنه: كان مما يقرأ في القرآن: الشيخ والشيخة إذا زنيا فارجموهما ألبتة نكالا من الله، والله عزيز حكيم.\nفهذه أقوال عامة المفسرين، وأما ابن بحر فإنه قال: المراد بقوله:\n(واللاتي يأتين الفاحشة من نسائكم)، وبقوله:\n⟦3:1143⟧\n(واللذان يأتيانها منكم) ما يتعاطى الرجال بعضهم من بعض.\nوالنساء بعضهن مع بعض، وبقوله: ﴿ٱلزَّانِيَةُ وَٱلزَّانِي﴾⟪24:2⟫ ما يتعاطى الرجل\nمع المرأة، قال: ولا نسخ في ذلك، قال: ويدل على ذلك أن\n(واللاتي يأتين) متضمنة للإناث فقط، (واللذان) يتضمن\nالمذكرين، قال: ولا يصح أن يقال: إن الذكر والمؤنث إذا اجتمعا\nغلب المذكر، لأن ذلك إنما يكون حيث تقدم لهما ذكر، نحو\nقوله: ﴿إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ﴾⟪33:35⟫\nقال: وقد روي عنه - صلى الله عليه وسلم -:\n\"مباشرة الرجل الرجل زنى، ومباشرة المرأة المرأة زنى\".\nوهذا الذي قاله وإن ساعده اللفظ فعدول عن سنن السلف."}, {"a": [16], "v": 3, "p": 1144, "ev": 3, "ep": 1144, "sid": 1345, "t": "قوله تعالى: (واللذان يأتيانها منكم فآذوهما فإن تابا وأصلحا فأعرضوا عنهما إن الله كان توابا رحيما (16)\nقد ذكر تفسيرها في الآية المتقدمة.\nوقال مجاهد: هما الرجلان\nالزانيان، يعني المتعاطيين اللواطة، يعبر عنها بالفاحشة.\nوقد روي عن النبي - صلى الله عليه وسلم - أن \"اللواطة الزنى الصغير \"، وظاهر قوله: ﴿فَإِن تَابَا وَأَصۡلَحَا فَأَعۡرِضُواْ عَنۡهُمَآۗ﴾⟪4:16⟫ يقتضي أن التوبة\nتسقط الحبس والأذى عن الزانيين، وقد قيل: الإعراض عنهما\nهو ترك التثريب المذكور في قوله - صلى الله عليه وسلم -:\n\"إذا زنت أمة أحدكم .. \" الخبر إلى قوله: \"فليبعها ولو بضفير، ولا يثرب عليها\"."}, {"a": [17], "v": 3, "p": 1145, "ev": 3, "ep": 1148, "sid": 1346, "t": "قوله تعالى: (إنما التوبة على الله للذين يعملون السوء بجهالة ثم يتوبون من قريب فأولئك يتوب الله عليهم وكان الله عليما حكيما (17)\nتعني أن قبول التوبة قد أخذ الله على نفسه تفضلا لمن تاب\nمن قريب إذا بدر منه سوء، وقوله: (بجهالة) فيه أقوال:\nالأول: يأتيه سهوا من غير قصد إلى الفاحشة.\nالثاني: عن جهل بكونه ذنبا.\nالثالث: أن يعلمه لكن لا يعلم كونه كبيرة، ولا قدر\nعقوبته.\nالرابع: أن يعلمه ويعلم عقوبته، لكن يتبع شهوته،\n⟦3:1146⟧\nومرتكب الذنب وإن كان يعلم كونه ذنبا يقال له جاهل، ومن\nهذا الوجه قال مجاهد: الجهالة: العمد، وقول من قال: الجهالة:\nالمعصية فعلى هذا، لأن كل معصية جهالة، وإن لم يكن كل\nجهالة معصية، وقوله: ﴿ثُمَّ يَتُوبُونَ مِن قَرِيبٖ﴾⟪4:17⟫ أي قبل\nالموت، بدلالة قوله - صلى الله عليه وسلم -:\n\"إن الله يغفر لعبده ما لم يقع الحجاب \".\n⟦3:1147⟧\nقيل: يا رسول الله: وما وقوع الحجاب؟ قال:\n\"موت النفس مشركة\".\nوروي: \"من تاب قبل موته بساعة تاب الله عليه \".\nوسمي مرة قليلا لقوله: ﴿قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ﴾⟪4:77⟫ والقريب والقليل\nفي نحو ذلك يتقاربان.\nوقال بعضهم: نبه بقوله: ﴿ثُمَّ يَتُوبُونَ مِن قَرِيبٖ﴾⟪4:17⟫ على لطيفة، وهي أن الإنسان إذا ارتكب ذنبا صدأ قلبه، فإن أقلع زال صدأه.\nوإن استمر رين على قلبه، وإن لم ينزع طبع عليه وأقفل.\nثم يتعذر عليه الرجوع، وعلى ذلك نبه بقوله في قصة\nالمنافقين) ﴿إِنَّكُمۡ رَضِيتُم بِٱلۡقُعُودِ أَوَّلَ مَرَّةٖ فَٱقۡعُدُواْ مَعَ ٱلۡخَٰلِفِينَ﴾⟪9:83⟫\nفإذا كان كذلك فحق لمن بدرت منه بادرة أن يتداركها قبل أن\n⟦3:1148⟧\nتصير الشهوة مستولية عليه، فتأبى الطباع على الناقل."}, {"a": [18], "v": 3, "p": 1148, "ev": 3, "ep": 1149, "sid": 1349, "t": "وقوله تعالى: (وليست التوبة للذين يعملون السيئات حتى إذا حضر أحدهم الموت قال إني تبت الآن ولا الذين يموتون وهم كفار أولئك أعتدنا لهم عذابا أليما (18)\nأعتدنا. قيل: أصله: أعددنا، فأبدل من إحدى الدالين تاء.\nوقيل: هو أفعلنا من العتاد أي العدة.\nوهو ادخار الشيء قبل الحاجة إليه.\nوالله تعالى غني عن الإعداد.\nوإنما القصد أنه لا يعجزه عذابهم حيث شاء.\nوالسيئات ههنا عبارة عن الشرك والكبائر.\nوحضور الموت: معاينة ملك الموت.\nبين تعالى أن التوبة تفوت إذا أخرت إلى ذلك، ولذلك لم ينفع\nإيمان من آمن عند رؤية العذاب، حيث قال تعالى: ﴿فَلَمۡ يَكُ يَنفَعُهُمۡ إِيمَٰنُهُمۡ لَمَّا رَأَوۡاْ بَأۡسَنَاۖ﴾⟪40:85⟫، وقال: ﴿يَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ﴾⟪6:158⟫ الآية، وقوله: (حتى إذا جاء أحدهم الموت قال رب ارجعون (99) لعلي أعمل صالحا) الآية.\n⟦3:1149⟧\nوجعل الناس قسمين: مقصرين في العمل غير تاركين للإيمان.\nوهم الذين عناهم الله بقوله: ﴿لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ﴾⟪4:17⟫\nوتاركين للعمل والإيمان وهم المعنيون بقوله: ﴿وَهُمۡ كُفَّارٌۚ﴾⟪4:18⟫."}, {"a": [19], "v": 3, "p": 1149, "ev": 3, "ep": 1154, "sid": 1350, "t": "قوله تعالى: (يا أيها الذين آمنوا لا يحل لكم أن ترثوا النساء كرها ولا تعضلوهن لتذهبوا ببعض ما آتيتموهن إلا أن يأتين بفاحشة مبينة وعاشروهن بالمعروف فإن كرهتموهن فعسى أن تكرهوا شيئا ويجعل الله فيه خيرا كثيرا (19)\nالعضل: التضييق عليها بالمنع من التزويج، وعضلت\nالدجاجة بيضها، والمرأة بحملها، والبقعة بأهلها، وداء عضال\nمنه، ومعنى قوله: ﴿أَن تَرِثُواْ ٱلنِّسَآءَ كَرۡهٗاۖ﴾⟪4:19⟫ ما روي أن الرجل إذا\nمات في الجاهلية يرث امرأته ورثته: أخا كان أو ابنا من غيرها، فإن\nشاء تزوجها بالصداق الأول، وإن شاء زوجها وأخذ مهرها،\n⟦3:1150⟧\nوقوله: (كرها)، وقرئ: (كرها). قال الفراء: ما أكره عليه\nالإنسان فكره وما كان من قبيل نفسه فكره.\nوقوله: ﴿وَلَا تَعۡضُلُوهُنَّ﴾⟪4:19⟫ قيل: هو نصب معطوف على قوله: ﴿أَن تَرِثُواْ﴾⟪4:19⟫.\nوذكر أن في قراءة عبد الله (ولا أن تعضلوهن)،\n⟦3:1151⟧\nوقيل: هو جزم على النهي.\nقال ابن عباس وقتادة: المنهي عن العضل الزوج إذا لم يحتج إلى المرأة، فيمسكها رغبة في مالها.\nوقيل: بل الوارث المانع لها من التزوج على سنة الجاهلية.\nوقيل: بل الولي، وكل هؤلاء منهيون في الشرع عن العضل.\nفيصح أن يكون خطابا لجماعتهم.\nوالفاحشة المذكورة ههنا.\nقال الحسن: هي الزنا، وللزوج أخذ الفدية إذا اطلع منها على ذلك،\n⟦3:1152⟧\nوقال ابن عباس: هي نشوزها، وقد تقدم الكلام في الخلع وجواز\nأخذ الفدية عن البضع.\nوقال الزبيري: الاستمناء من العضل، وكان للزوج منعها على ما أمر به تعالى في قوله: ﴿فَأَمۡسِكُوهُنَّ فِي ٱلۡبُيُوتِ﴾⟪4:15⟫، وذلك قبل نزول الحد.\nوقوله: ﴿وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ﴾⟪4:19⟫ أي حسب ما يعرفه العقل\n⟦3:1153⟧\nوالشرع، وقيل: هو النصفة والنفقة والإجمال في القول.\nوفي قوله: ﴿فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا﴾⟪4:19⟫ الآية.\nأي رب شيء تكرهه، ويكون في ذلك خير، تنبيها على أمرين:\nأحدهما: أن لا يجب للإنسان أن يتبع الهوى، بل يفعل ما يقتضيه\nالعقل والشرع.\nوالثاني: التنبيه على كراهية الطلاق المدلول عليه بقوله - صلى الله عليه وسلم -: \"أبغض الحلال إلى الله تعالى الطلاق \".\nوروي عنه - صلى الله عليه وسلم -:\n\"تزوجوا ولا تطلقوا، فإن الله لا يحب الذواقين والذواقات \".\nوقال بعضهم: ذلك تنبيه أنه ربما كانت الكراهية\n⟦3:1154⟧\nتعرض لمصلحة، قال: وذلك حث على مفارقتها حيث عدم\nموافقتها، وإن كانت النفس تكره ذلك، وعلى هذا نبه بقوله\nتعالى: ﴿وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلّٗا مِّن سَعَتِهِۦۚ﴾⟪4:130⟫."}, {"a": [20], "v": 3, "p": 1154, "ev": 3, "ep": 1156, "sid": 1355, "t": "قوله تعالى: (وإن أردتم استبدال زوج مكان زوج وآتيتم إحداهن قنطارا فلا تأخذوا منه شيئا أتأخذونه بهتانا وإثما مبينا (20)\nالبهتان: الكذب الذي يبهت سامعه لفظاعته.\nويستعمل في الفعل استعمال الصدق والكذب.\nولذلك قال ابن عباس: بهتانا: ظلما كبيرا.\n(وإثما مبينا): ذنبا ظاهرا، بين أنه لا يجوز لكم\n⟦3:1155⟧\nالرجوع فيما أعطيتموهن طلقتموهن أو أمسكتموهن، وخص\nحال الاستبدال ليدخل فيه الحالة الأخرى، وذلك توكيد لقوله:\n﴿وَلَا تَعۡضُلُوهُنَّ﴾⟪4:19⟫ وقد استثنى من ذلك المطلقات قبل الدخول\nبهن، لقوله: ﴿وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِيضَةٗ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ﴾⟪2:237⟫ واستثنى منه أيضا حال الافتداء المذكور في قوله: ﴿فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ بِهِۦۗ﴾⟪2:229⟫ الآية منسوخة بقوله: ﴿إِلَّآ أَن يَخَافَآ﴾⟪2:229⟫، والصحيح أنها ليست منسوخة، وقد تقدم ذلك في سورة البقرة،\n⟦3:1156⟧\nوروي أن رجلا كان عليه لامرأته من صداقها ألف دينار، فوضعتها له.\nفطلقها وتزوج غيرها، فارتفعا إلى عبد الملك فقال: رد عليها.\nفقال:\nأليس الله يقول: ﴿فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ﴾⟪4:4⟫.\nفقال: اقرأ الآية الأخرى: ﴿وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ﴾⟪4:20⟫ الآية."}, {"a": [21], "v": 3, "p": 1156, "ev": 3, "ep": 1158, "sid": 1357, "t": "قوله تعالى: (وكيف تأخذونه وقد أفضى بعضكم إلى بعض وأخذن منكم ميثاقا غليظا (21)\nيقال: أفضى إلى فلان أي وصل إلى فضاء منه أي سعة غير محظورة.\nفمن الفقهاء من جعل ذلك عبارة عن الخلوة حصل معها المسيس أو بم يحصل، ومنهم من جعله\n⟦3:1157⟧\nكناية عن المسيس، وإليه ذهب ابن عباس ومجاهد والسدي.\nونبه أن المهر بإزاء ذلك المعنى، وقد نلتموه منهن فلا حق لكم إذا\nعليهن، والميثاق الغليظ: قيل هو ما قاله - صلى الله عليه وسلم -: \"أخذتموهن بأمانة الله، واستحللتم فروجهن بكلمة الله \".\nوقال مجاهد: الميثاق كلمة النكاح.\nوقال الحسن: هو قول: ﴿فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ﴾⟪2:229⟫\n⟦3:1158⟧\nوقيل: قول الذين يزفونها، وكل ذلك يصح إرادته بالميثاق."}, {"a": [22], "v": 3, "p": 1158, "ev": 3, "ep": 1163, "sid": 1359, "t": "قوله تعالى: (ولا تنكحوا ما نكح آباؤكم من النساء إلا ما قد سلف إنه كان فاحشة ومقتا وساء سبيلا (22)\nاختلفوا في النكاح ههنا، فحمله أصحاب أبي حنيفة على الجماع.\nوقال: هو حقيقة فيه، فحرموا كل امرأة باضعها الأب حلالا أو\nحراما على الابن.\nوحمله الشافعي على العقد، وقال: هو حقيقة فيه.\nولم يحرم من النساء على الابن إلا ما تزوج بها أبوه دون\n⟦3:1159⟧\nمن زنى بها، والصحيح أنه للعقد، لأن أسماء الجماع والفرج\nوالغائط في لسانهم كنايات، وذلك أنهم لما عنوا بإخفاء هذه\nالأشياء أخفوا أيضا أسماءها، فعدلوا عن التصريح إلى الكنايات.\nحتى إنهم متى عرف فيما بينهم كناية في شيء من ذلك عدلوا إلى\nكناية أخرى، ومن تتبع كلامهم عرف ما قلته، فكيف يستعيرون\nلفظ الجماع لما هو أحسن عندهم منه، ثم لا خلاف أن العقدية\nمراد، ولا خلاف أيضا أن الوطء بملك اليمين يجري مجرى العقد\nفي العقد بها، وقوله: ﴿مَا نَكَحَ ءَابَآؤُكُم﴾⟪4:22⟫ قيل: هو في موضع\nالمفعول، فوضع ما الذي هو للجنس موضع من الذي هو\n⟦3:1160⟧\nللنوع، وقيل: معناه لا تنكحوا كنكاح آبائكم، فما في موضع\nالمصدر، وقوله: ﴿إِلَّا مَا قَدۡ سَلَفَۚ﴾⟪4:22⟫.\nقال: بعضهم: معناه بعدما قد سلف كقولك: لا تبع من متاعي إلا ما قد بعت.\nوقول الشاعر:\nهجاؤك إلا أن ما كان قد مضى. . . علي كأثواب الحرام المهيم\nوقيل: هو بمعنى لكن على الاستئناف، كأنه قيل: لكن ما قد\n⟦3:1161⟧\nسلف أنه كان فاحشة ومقتا.\nوقال بعضهم: تقديره ولا تنكحوا ما نكح آباؤكم، إنه كان فاحشة ومقتا وساء سبيلا، إلا ما قد سلف أي ما قد سلف ليس بفاحشة، وهذا لا يصح من أجل اللفظ، فإن ما يتصل بما بعد (أن) لا يقدم عليه، لا تقول:\nعمرا إن زيدا يضرب، وتعنى أن زيدا يضرب عمرا.\nوتحقيق هذا الاستثناء أن قوله: ﴿وَلَا تَنكِحُواْ﴾⟪4:22⟫ دل على أنه محرم، وتعاطي\nالمحرم يقتضي العقوبة، فكأنه قيل: تستحقون العقوبة بنكاح ما\nنكح آباؤكم إلا ما قد سلف، فإن، ذلك متجافى عن عقوبته عنكم.\nولا يجوز أن يكون معناه متجافى عن الإقرار عليه، فإنه مجمع\nأن لا يقار عليه أحد إلا حكاية عمن لا يعتد به.\n⟦3:1162⟧\nوقوله: ﴿إِنَّهُۥ كَانَ فَٰحِشَةٗ﴾⟪4:22⟫، قيل: معناه نكاحهن بعد النهي فاحشة.\nوكان زائدة، وقيل: عنى أنه كان فاحشة.\nمن قبل تنبيها أن ذلك لم يكن من الأشياء التي ورد بها الشرع.\nثم نسخ، كذا كثير من الأحكام، بل كان ذلك من المستشنع\nالممقوت، ولذلك كان يسمى ولد الرجل من امرأة أبيه المقتي.\nوقوله: (إنه) أي إن ذلك النكاح، ودل عليه بذكر الفعل،\n⟦3:1163⟧\nكما دل على السفه بلفظ السفيه في قول الشاعر:\nإذا نهي السفيه جرى إليه. . . . . . . . . . . . . . . . . . . . . . . ."}, {"a": [23], "v": 3, "p": 1163, "ev": 3, "ep": 1171, "sid": 1364, "t": "قوله تعالى: (حرمت عليكم أمهاتكم وبناتكم وأخواتكم وعماتكم وخالاتكم وبنات الأخ وبنات الأخت وأمهاتكم اللاتي أرضعنكم وأخواتكم من الرضاعة وأمهات نسائكم وربائبكم اللاتي في حجوركم من نسائكم اللاتي دخلتم بهن فإن لم تكونوا دخلتم بهن فلا جناح عليكم وحلائل أبنائكم الذين من أصلابكم وأن تجمعوا بين الأختين إلا ما قد سلف إن الله كان غفورا رحيما (23)\nقال ابن عباس: حرم الله أربع عشرة امرأة:\nسبعا من جهة النسب، وسبعا من جهة السبب،\n⟦3:1164⟧\nفالمحرمات من جهة النسب: الأمهات والبنات والأخوات\nوالعمات والخالات وبنات الأخ وبنات الأخت، ومن جهة\nالنسبب: أمهاتكم اللاتي أرضعنكم، وأخواتكم من الرضاعة.\nوأمهات نسائكم، وربائبكم اللاتي في حجوركم، وحلائل\n، أبنائكم الذين من أصلابكم، وأن تجمعوا بين الأختين، وقد\nقال قبل: ﴿وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم﴾⟪4:22⟫.\nفقوله: (أمهاتكم) تناولهن والجدات وإن علون، وكذا البنات:\nتناولهن وبنات الأولاد وإن سفلن، وكذلك الأخوات يتناول\nالتي للأب والتي للأم والتي لهما، وكذلك بنات الأخ وبنات\nالأخت: يتناول بناتهما على ذلك الحد بناتهما وإن سفلن، وخص\nتحريم العمات والخالات دون أولادهن، وجاز أن تكون بنات\nالأخ وبنات الأخت مفردين، لأن الأخ والأخت يتناول كل واحد\nمنهما، وكان لفظ الواحد ههنا أخص لإضافة الجمع إليهما،\n⟦3:1165⟧\nوإنما قال: (وأمهاتكم اللاتي أرضعنكم) تنبيها على تأكيد\nتحريم الرضاع أنها تجري مجرى النسب، ولأن في ذكر\n(وأمهاتكم اللاتي) تنبيها أن ليس كل رضاع يحرم، إشارة\nإلى ما روي من قوله - صلى الله عليه وسلم -:\n\"لا تحرم الإملاجة والإملاجتان \"\n⟦3:1166⟧\nوقوله: (من نسائكم اللاتي دخلتم بهن) لا خلاف أنه صفة\nلربائبكم، وأنه لا يحرم التزوج بهن إلا بالدخول بأمهاتهن.\nواختلف هل يرجع إلى قوله: ﴿وَأُمَّهَٰتُ نِسَآئِكُمۡ﴾⟪4:23⟫ مع كونه\nشرطا في الربائب؟، فروي عن أمير المؤمنين علي عليه السلام\nأنه يرجع إليهما، وأن من طلق امرأته قبل الدخول بها فله أن\nيتزوج بأمها، وقال عمر وابنه وابن مسعود: ليس يرجع إلا إلى\nالربائب، وذكروا أن أم المرأة تحرم بنفس العقد، وأكد ذلك\n⟦3:1167⟧\nبما روي عن عمرو بن شعيب عن أبيه عن جده إلى النبي\n- صلى الله عليه وسلم - قال:\n\"أيما رجل نكح امرأة فدخل بها أو لم يدخل بها فلا يحل له نكاح أمها\".\nوحكي عن زيد أنه فصل بين أن يطلقها قبل الدخول أو تموت عنه.\nولم يحرم بالطلاق وحرم بالموت.\nوأجرى الموت مجرى الدخول، كما جعل الفقهاء في استقرار المهر،\n⟦3:1168⟧\nوذهب عامة الفقهاء إلى أن لا فرق بين تحريم ربيبتك في حجرك\nكانت أو لم تكن إلا ما حكى إسماعيل بن إسحاق: أن\nامرأتي توفيت فلقيت عليا عليه السلام فقال: ألها بنت؟ فقلت:\nنعم، وهي بالطائف، فقال: أكانت في حجرك؟ فقلت: لا.\nفقال: انكحها، فقلت: فأين قوله: (وربائبكم اللاتي في حجوركم)\nفقال: إنما ذلك إذا كان في حجرك، وما قاله\n⟦3:1169⟧\nفهو ظاهر الآية.\nواختلف في قوله: (اللاتي دخلتم بهن) هل يقتضي الزنا؟\nفمنهم من قال: يتناوله وعليه تأول ﴿وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم﴾⟪4:22⟫ ومن قال: لا يتناوله، وقد تقدم ذلك.\nوقوله: ﴿وَحَلَٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ مِنۡ أَصۡلَٰبِكُمۡ﴾⟪4:23⟫ إنما خص ذلك\nليخرج منه المتبنى، فذلك في معنى قوله: ﴿فَلَمَّا قَضَىٰ زَيۡدٞ مِّنۡهَا وَطَرٗا زَوَّجۡنَٰكَهَا﴾⟪33:37⟫ الآية.\nوالحلائل ههنا كالأزواج، ثم.\nوفي قوله: ﴿وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا مَا قَدۡ سَلَفَۗ﴾⟪4:23⟫\nتنبيه أنه لا يصح العقد عليهما معا في الإسلام.\nومتى فعل فعقدهما باطل، ومتى عقد على إحداهما فعقد الثانية باطل،\n⟦3:1170⟧\nوعند أبي حنيفة: لا يجوز التزويج بإحدى الأختين إذا كانت الأخرى منه في عدة، ولا يجوز وطؤهما بملك اليمين عند عامة الفقهاء، ومتى وطئت\nإحداهما لا يجوز وطء الأخرى إلا بإخراج الأولى من ملكه.\nوقال أمير المؤمنين: أحلتهما آية وحرمتهما آية، أي عموم\n⟦3:1171⟧\nقوله: ﴿وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ﴾ يقتضي تحليلهما، وعموم قوله:\n﴿وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ﴾⟪4:23⟫ يقتضي تحريمهما.\nقال: وأما أنا فأحرم ذلك، وروي عن ابن عباس أنه أجاز ذلك.\nوقوله: ﴿إِلَّا مَا قَدۡ سَلَفَۗ﴾⟪4:23⟫ يراد به ما يراد بقوله ﴿مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدۡ سَلَفَۚ﴾⟪4:22⟫."}, {"a": [24], "v": 3, "p": 1171, "ev": 3, "ep": 1182, "sid": 1372, "t": "قوله تعالى: (والمحصنات من النساء إلا ما ملكت أيمانكم كتاب الله عليكم وأحل لكم ما وراء ذلكم أن تبتغوا بأموالكم محصنين غير مسافحين فما استمتعتم به منهن فآتوهن أجورهن فريضة ولا جناح عليكم فيما تراضيتم به من بعد الفريضة إن الله كان عليما حكيما (24)\n⟦3:1172⟧\nأصل الإحصان والحصن من الحصن، ومنه درع حصينه\nلكونه حصنا للبدن، وكذلك فرس حصان، وبهذا النظم قال\nالشاعر:\n. . . أن الحصون الخيل لا مدر القرى\nوالحصان في الجملة المحصنة أي الممنوعة، إما بعفتها أو\nبزوجها أو بمانع من شرفها أو حريتها، ولما كان الحصن في\n⟦3:1173⟧\nأكثر المواضع يصح أن يكون من جهة الإنسان نفسه، وأن يكون\nمن جهة غيره صح أن يقال محصن ومحصن، وهذا الموضع لما كان\nالمقصود به التزويج قرئ (المحصنات) لا غير، إذ كان سبب\nإحصانها الزوج، والسفاح الزنا، وسمي بذلك لكون ذلك الماء\nمضيعا، إذ وضع في غير الموضع الذي يجب أن يوضع فيه.\nوقوله: ﴿وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ﴾⟪4:24⟫ منهم من أجرى على العموم.\nوقال: حدوث الملك في الأمة يفرق بين الأمة وزوجها.\nوروي ذلك عن ابن عباس وابن مسعود، وروي في ذلك أن\n⟦3:1174⟧\nالنبي - صلى الله عليه وسلم - قال: \"بيع الأمة طلاقها\".\nومنهم من خص ذلك في المشركات.\nوجعل قوله: ﴿إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ﴾⟪4:24⟫ استثناء منها.\nوقال: كل امرأة سبيت فقد حلت لسابيها، واستدل في\nذلك بما روى أبو سعيد الخدري أن النبي - صلى الله عليه وسلم -\nبعث جيشا إلى أوطاس فأصابوا سبايا لها أزواج من المشركين، فتحرجوا من\n⟦3:1175⟧\nغشيانهن، فأنزل الله ﴿وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ﴾⟪4:24⟫\nوظاهر ذلك يقتضي أن الزوجين إذا سبيا معا أو مفترقين\nأن النكاح يبطل، كما قال مالك.\nبخلاف ما قال أبو حنيفة حيث قال:\nإذا سبيا معا لا يبطل النكاح.\nوظاهر الآية يقتضي أنه يصح وطؤها على كل حال.\nوإنما علم وجوب استبرائها بالسنة.\nوقال طاوس:\n⟦3:1176⟧\nوابن المسيب: القصد بالآية نهي عن الزنا.\nوالمحصنات محرمة على كل واحد منكم إلا امرأته المعقود عليها\nبالنكاح أو ملك اليمين، فهذا معنى ﴿إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ﴾⟪4:24⟫.\nويكون هذا أمرا إنما مدح به في قوله: (والذين هم لفروجهم حافظون (5) إلا على أزواجهم أو ما ملكت أيمانهم).\nوقوله: ﴿كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ﴾⟪4:24⟫\nقيل: هو مصدر مؤكد من غير لفظ الأول.\nوقيل: هو إغراء وحث والعامل فيه فعل مضمر.\nوقال الكوفيون: هو إغراء\n⟦3:1177⟧\nوالعامل فيه عليكم، كأنه قيل: عليكم كتاب الله، وعلى ذلك\nحملوا قوله:\nيا أيها الماتح دلوي دونكا. . . إني رأيت الناس يحمدونكا\nوقوله: ﴿وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ﴾⟪4:24⟫\nقال السدي: ما وراء المذكورات،\n⟦3:1178⟧\nوقال عطاء: ما وراء ذات المحارم، قيل: والصحيح أن المراد\nما وراء كل ما حرم الله كتابا وسنة.\nواختلف هل في قوله: ﴿مَّا وَرَآءَ ذَٰلِكُمۡ﴾⟪4:24⟫ نسخ؟\nفقال بعضهم: نسخ منه بعضه بقوله - صلى الله عليه وسلم -:\n\" لا تنكح المرأة على عمتها ولا على خالتها، ولا الصغرى على\nالكبرى، ولا الكبرى على الصغرى\".\nوقال بعضهم: لا نسخ\n⟦3:1179⟧\nفيه، وإنما ذلك تخصيص للآية، وقيل: ولأنه لما حرم الجمع\nبين الأختين للنسب الذي بينهما نبه على تحريم ذلك، لأن إحداهما\nلو كانت ذكرا لم تحل له الأخرى من قبل النسب.\nولا ينتقض ذلك بأن يجمع الرجل بين المرأة وبين ابنة زوجها الأول، وإن كانت إحداهما لو كانت ذكرا لم تحل له الأخرى، لأن ذلك التحريم ليس من جهة النسب.\nوقوله: ﴿أَن تَبۡتَغُواْ بِأَمۡوَٰلِكُم﴾⟪4:24⟫ يقتضي أن لابد من المهر\nسمي أو لم يسم في العقد.\nواستدل أصحاب أبي حنيفة في أن لا يصح أن يجعل مهرا\nإلا ما وقع عليه اسم المال، وعلى ذلك\n⟦3:1180⟧\nقوله: ﴿وَءَاتُواْ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةٗۚ﴾⟪4:4⟫.\nوقوله: ﴿فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ﴾⟪4:24⟫\nكناية عن الدخول، وأصله الانتفاع به.\nوقوله: ﴿فَـَٔاتُوهُنَّ أُجُورَهُنَّ﴾⟪4:24⟫ أي مهورهن.\nوروي عن ابن عباس أنه حمل ذلك على متعة النساء.\nوروي عنه أنه قال: نزل \"فما استمتعتم به منهن إلى أجل مسمى\"،\n⟦3:1181⟧\nوقال قتادة: كذلك هو في قراءة أبي.\nوحمل ذلك عامة الصحابة على النكاح.\nوقد ورد في تحريم المتعة أخبار كثيرة، ذكرها الفقهاء في كتبهم.\nونبه بقوله: ﴿وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ﴾⟪4:24⟫\n⟦3:1182⟧\nأن لا جناح في وضعه بعد التسمية وإعطائه إياها والزيادة فيه."}, {"a": [25], "v": 3, "p": 1182, "ev": 3, "ep": 1192, "sid": 1383, "t": "قوله تعالى: (ومن لم يستطع منكم طولا أن ينكح المحصنات المؤمنات فمن ما ملكت أيمانكم من فتياتكم المؤمنات والله أعلم بإيمانكم بعضكم من بعض فانكحوهن بإذن أهلهن وآتوهن أجورهن بالمعروف محصنات غير مسافحات ولا متخذات أخدان فإذا أحصن فإن أتين بفاحشة فعليهن نصف ما على المحصنات من العذاب ذلك لمن خشي العنت منكم وأن تصبروا خير لكم والله غفور رحيم (25)\nالطول: سعة في العطية، وهو أخص من النيل.\nفإن النيل يقال في القليل والكثير.\nوالطول لا يقال إلا فيما يزيد على غيره كالطول في أنه يقال اعتبارا بغيره.\nوقال ابن عباس وعامة الصحابة: هو\n⟦3:1183⟧\nالغنى، وذلك أن يجد من المال ما يجعله صداق حرة.\nوإليه ذهب الثوري، والشافعي.\nوقوى ذلك بما رواه جابر عن النبي - صلى الله عليه وسلم -:\n\"من وجد ما يتزوج به حرة فلا ينكح أمة\".\nومال أبو حنيفة: هو أن يكون تحته حرة.\nوقال بعض الصحابة: هو أن يجد في قلبه غنى عنها بأن لا يهواها.\nوحكي عن مالك:\n⟦3:1184⟧\nلا بأس أن يتزوج الحرة على الأمة، والأمة على الحرة.\nوأصل العنت: الشدة نحو العند، لكن العنات أبلغ من العناد.\nلأنه هو المؤدي إلى الهلاك.\nوقال تعالى: ﴿وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ﴾⟪2:220⟫ ومنه قيل: أكمة عنوت.\nوقد فسر بالزنا تفسير عموم بخصوص\n⟦3:1185⟧\nإذ هو المقصود منه، وهو المؤدي إلى هلاك الآخرة.\nولما بين الله تعالى المحرمات، وأحل ما وراء ذلك\nبشروط ذكرها عقب ذلك بمن لا يستطيع مهر الحرائر ونفقتهن.\nفأباح لهم تزوج الأمة، إذ هي أخف مهرا ونفقة.\nوشرط في جواز التزوج بها شرطين:\nعدم الطول، وخوف العنت.\nوفصل بين بعض هذا الحكم وبعضه بفصلين:\nأحدهما: قوله: ﴿وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضٖۚ﴾⟪4:25⟫.\nوالثاني: حكم الأمة كيف ينبغي أن تكون صفتها حتى يجوز التزوج بها؟\nومثل هذا الاعتراض يسمى في البلاغة الالتفات.\nوقوله: ﴿أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ﴾⟪4:25⟫ فمنهم من جعل الإيمان شرطا.\nوقال: يجوز للرجل أن يتزوج بالأمة، وإن وجد طول الذمية الحرة.\nوقوي بقوله: ﴿وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ مِّن مُّشۡرِكَةٖ﴾⟪2:221⟫.\nومنهم من قال: ذكر المؤمنات على طريق الفضل،\n⟦3:1186⟧\nولا يجوز التزوج بالأمة مع طول الذمية، قال: لأن العلة التي\nلأجلها منع من التزوج بالأمة تعرض الولد للاسترقاق، وذلك\nمعدوم في الكتابيات الحرائر، فيجب أن يكون التزوج بها أولى\nمن الأمة.\nوقوله : ﴿فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم﴾⟪4:25⟫\nقال الأصم: أجمعوا أنه أريد به التزوج، وشرط الإيمان في الأمة.\nوقال الحسن ومجاهد والثوري وأبو حنيفة: هو على الاستحباب، فأجازوا\nالتزوج بالأمة الكتابية.\nوقال مالك والشافعي والأوزاعي: لا يجوز نكاح الأمة الكتابية المؤمنة.\nلأن ما أبيح بشرط فلا يجوز ذلك على غير ذلك الشرط، سيما إذا كان الشرط بيانا لحكم.\nوقوله: ﴿وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ﴾⟪4:25⟫ تنبيه على أن الاعتبار بالمواصلات\nفي الأحكام الدنيوية بظاهر الإيمان لا بحقائقه، فإن الله يتولى السرائر،\n⟦3:1187⟧\nوقوله: ﴿بَعۡضُكُم مِّنۢ بَعۡضٖۚ﴾⟪4:25⟫ تنبيه على أمور منها:\nمعنى ما قال تعالى: ﴿وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا﴾⟪16:72⟫\nومنها ما دل عليه النبي - صلى الله عليه وسلم - بقوله:\n\"مولى القوم \".\nومنها أنهم كانوا يعيرون بالهجنة، فأراد أن يزيل هذا الاعتقاد عنهم،\n⟦3:1188⟧\nوقوله: ﴿فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ﴾⟪4:25⟫، أي أربابهن، وذلك يقتضي\nأن لا يصح تزوج الأمة إلا بإذن أهلها، ويقوي ذلك قوله\n- صلى الله عليه وسلم -:\n\"إذا تزوج العبد بغير إذن، سيده فهو عاهر\".\nوقال عطاء: إذنه على الاستحباب لا على الوجوب.\nوقوله تعالى: ﴿وَءَاتُوهُنَّ أُجُورَهُنَّ﴾⟪4:25⟫\nقيل: تقديره بإذن أهلهن، لكن حذف، كقوله ﴿وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ﴾⟪33:35⟫\n⟦3:1189⟧\nوقال بعضهم: أجورهن: نفقاتهن والأول هو الوجه، لأن\nالنفقة تتعلق بالتمكين لا بالعقد.\nوقال مالك: تستحق الأمة المهر.\nواستدل بهذه الآية على أن الرقيق يملك.\nوقوله: (بالمعروف) هو أي على ما عرف من حكم الشرع.\nوقيل: على سبيل الهبة، فإن المعروف يعبر به عن العطية.\nوذلك كقوله (نحلة).\nوقوله: ﴿مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتٖ﴾⟪4:25⟫ أمر بأن يكون\nوطؤها لازما، ولا على سبيل المخادنة، واشتر اط الأمرين أن\nقوما كانوا يبيحون اتخاذ الجارية خدنا،\n⟦3:1190⟧\nوقرأ الحسن: \"محصنات\"، وقال: معناها عفائف.\nولم يجوز نكاح الأمة الزانية التي أقيم عليها الحد.\nوقوله: ﴿فَإِذَآ أُحۡصِنَّ﴾⟪4:25⟫ أي زوجن.\nوقرئ: \"أحصن\"، أي تزوجن، وقيل: أسلمن.\nوالأول أصح، وعلى التفسير الثاني\n⟦3:1191⟧\nيقتضي أن الأمة إذا زنت - وإن لم تكن مزوجة - تحد\nبحكم الآية، وأن الكتابية لا تحد وإن كانت مزوجة.\nوقوله: ﴿ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ﴾⟪4:25⟫\nقد تقدم أنه يتعلق بما قبله.\nوقوله: ﴿وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ﴾⟪4:25⟫\nإبانة أن الاختيار ترك نكاح الأمة رأسا.\nلئلا يكون ولده رقيقا لغيره.\nوبين بقوله: ﴿وَٱللَّهُ غَفُورٞ رَّحِيمٞ﴾⟪4:25⟫\nوأحكام القرآن لابن العربي (1 4 5 4)، والمحرر الوجيؤ (4 86).\nوالجامع لأحكام القرآن (5 143).\nأي أسلمن وهو قول ابن مسعود والشعبي والزهري والسدي والجمهور\nكما ذكر ابن عطية. انظر: جامع البيان (8 99 ا - ا 20)، وأحكام\nالقرآن للجصاص (2 68 1)، والنكت والعيون (1 473)، وأحكام\nالقرآن لابن العربي (1 4 0 4)، والمحرر الوجيؤ (4 86)، والجامع\nلأحكام القرآن (5 143).\nانظر: أحكام القرآن للجصاص (2 168، 69 1)، وأحكام القرآن\nلابن العربي (1 405، 505)، والمحرر الوجيؤ (4 86)، والجامع\nلأحكام القرآن (5 43 1، 44 1)، وتفسير غر ائب القرآن (2 397).\nانظر: اقوال العلماء في تفسير العنت في: معاني القرآن للزجاج (2 42).\nوأحكام القرآن لابن العربي (1 407).\nانظر: جامع البيان (8 207، 208)، ومعاني القرآن للزجاج (2 42).\nوأحكام القرآن للجصاص (2 175)، وأحكام القرآن لابن العربي\n(1 7 5 4)، ومعالم التنزيل (2 98 1)، والمحرر الوجيؤ (4 88!.\nوالجامع لأحكام القرآن (5 147).\n1191\n⟦3:1192⟧\nأن هذا وإن كان مكروها فقد غفر لكم، ورحمكم في إباحته.\nفالأول هو تبين العادة، والثاني وهو قوله: ﴿تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ﴾⟪4:25⟫\nحث على مكرمة، كقوله - صلى الله عليه وسلم -:\n\"إياكم وخضراء الدمن \".\nوكثيرا ما يجمع تعالى بين الحكم المراد وبين الفضل ليكون قد\nأدب عباده بالأمر."}, {"a": [26], "v": 3, "p": 1192, "ev": 3, "ep": 1194, "sid": 1393, "t": "قوله تعالى: (يريد الله ليبين لكم ويهديكم سنن الذين من قبلكم ويتوب عليكم والله عليم حكيم (26)\nالسنن: جمع السنة أي الطريقة المستقيمة.\nوأصلها من سن الماء، وعنه استعير من سن السيف\nلما كان يشبه عند صقله بالماء.\nواستعير منه سن الفرس، كما يقال: صقل الفرس.\nواللام في قوله: (ليبين)\n⟦3:1193⟧\nفيه قولان؟ قال الفراء: أردت أن يكون كذا\nوأردت ليكون، ﴿وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِينَ﴾⟪39:12⟫.\nوأمرت أن أعدل.\nقال: ويعدى هذان الفعلان باللام تارة.\nلكونهما طالبين للفعل المستقبل.\nوقال بعضهم: بل الفعل محذوف، واللام للعلة على تقدير:\nيريد الله ما يريد لأن يبين.\nوقوله: ﴿سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ﴾⟪4:26⟫\nمنهم من خص وقال: أراد أن يحرم علينا ما حرم عليهن\nبالنسب والرضاع والمصاهرة.\nوقيل: عنى ول ما ذكره في قوله: ﴿ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ﴾⟪16:123⟫\n⟦3:1194⟧\nومنهم من أخذه أعم من ذلك، فقال: إن الله تعالى شرع لكل\nأمة عبادة ومكارم، ولم يختلف حكم أصولها، وإن اختلفت\nفروعها، وعلى ذلك قال: ﴿شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ﴾⟪42:13⟫.\nفبين أنه يريد أن تكون هذه الأمة جارية مجرى هؤلاء في ذلك.\nوقيل: عنى أنه يبين لكم طريق من قبلكم إلى الجنة.\nوهو المسئول في قوله تعالى: ﴿وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ﴾.\nوبين أنه أراد به ذلك لعلمه وحكمته."}, {"a": [27], "v": 3, "p": 1194, "ev": 3, "ep": 1198, "sid": 1395, "t": "قوله تعالى: (والله يريد أن يتوب عليكم ويريد الذين يتبعون الشهوات أن تميلوا ميلا عظيما (27)\nالميل وإن كان عاما في الميل إلى الخير والشر.\nفالمقصود به ههنا الجور عن قصد السبيل.\nولما كان جميع عبادة الله بالقول المجمل ضربين،\n⟦3:1195⟧\nصقل العقل، وقمع الشهوة، وكل أمر ونهي فذريعة إليهما.\nصار اتباع الشهوة سبب كل مذمة، فلذلك عبر بمتبع الشهوات عن\nالفاسق والكافر، وعلى هذا قوله: ﴿أَضَاعُواْ ٱلصَّلَوٰةَ وَٱتَّبَعُواْ ٱلشَّهَوَٰتِۖ﴾⟪19:59⟫.\nفإن قيل: فليس اتباع الشهوات مذموما في كل حال.\nبل منها ما هو محمود؟\nقيل: قد قال بعض المتكلمين وبعض المفسرين:\nعنى بذلك بعض الشهوات.\nوقال بعضهم: عنى من يتبع الشهوات كلها.\nوالصحيح أن اتباع الشهوة في\n⟦3:1196⟧\nكل حال مذموم، لأن ذلك هو الائتمار لها من حيث ما دعت.\nوما سوغ من تعاطي ذلك، فليس جواز تعاطيه من حيث دعت\nالشهوة إليه، بل من حيث سوغ العقل أو الشرع، فذلك هو\nاتباع لهما، ويؤكد ذلك قوله: ﴿وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ﴾⟪38:26⟫\nوقوله: ﴿وَلَٰكِنَّهُۥٓ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ﴾⟪7:176⟫\nوقيل: عبد الشهوة أذل من عبد الرق.\nإن قيل: كيف أدخل اللام في قوله: ﴿يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ﴾⟪4:26⟫\nولم يدخله في قوله: ﴿وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ﴾⟪4:27⟫؟\nوكيف أعاد ذكر إرادته التوبة؟ ولم قال: ﴿وَٱللَّهُ يُرِيدُ﴾⟪4:27⟫\nفقدم ذكر المخبر عنه، ثم قال: ﴿وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ﴾⟪4:27⟫\nفأخر المخبر عنه؟\nقيل: أما إدخال اللام في الأول فلأنه عنى أنه يريد ما يريد\nلأجل التوبة عليهم، وأراد بقوله ﴿أَن يَتُوبَ﴾⟪4:27⟫ أنه كما أراد ما هو\nسبب التوبة عليهم، فقد أراد التوبة عليهم، إذ قد يصح إرادة\nسبب الفعل دون الفعل نفسه، ففي هذا ظهور فائدة اللام وحسن\n⟦3:1197⟧\nإعادته، واقتضى إعادته أيضا ذكر قوله: ﴿وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ﴾⟪4:27⟫\nليبين أن إرادة الله لكم مضادة لما يريدونه.\nوأما تأخير المخبر عنه في قوله: ﴿وَيُرِيدُ ٱلَّذِينَ﴾⟪4:27⟫ فيجوز أنه\nجعل الواو للحال لا العطف، تنبيها أنه يريد التوبة عليكم\nفي حال ما يريدون أن تميلوا، فخالف بين الإخبارين ليبين أن\nالثاني ليس على العطف.\nوتخصيص الميل العظيم هو أن الإنسان قد يترك تحري الخيرات\nمن الإيمان والأعمال الصالحة، إما لعارض شغل وإما لكسل.\nوإما لضلالة، وهو أن يسبق إلى اعتقاد باطل فينشأ عليه.\nوإما لفسق وهو أن يكون مع الاعتقاد يستلذ تعاطي الشر.\nومن تركه للشغل فهو أسهل معالجة ممن يتركه لكسل.\nومن تركه للكسل\n⟦3:1198⟧\nفهو أسهل ممن تركه للضلال، وكذا ما بعده، وكأنه قال:\nإنهم أرادوا أن يجوروا جورا عظيما، ليكونوا أبعد من الرشاد.\nوالإشارة بالمعنى إلى نحو قوله تعالى: ﴿وَدُّواْ لَوۡ تَكۡفُرُونَ كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءٗۖ﴾⟪4:89⟫، وعلى ذلك قوله: ﴿وَيُرِيدُونَ أَن تَضِلُّواْ ٱلسَّبِيلَ﴾⟪4:44⟫\nفإن قيل: فهلا خص الميل ليزيل الإشكال، إذ الميل تارة إلى الحق\nوتارة إلى الباطل؟\nقيل: لما كانت العدالة وسطا وكان أطرافها كلها جوزا.\nولذلك سميت وسطا، وسواء، وعدلا، وصراطا مستقيما.\nنبه بإطلاق لفظ الميل: أن الكفار يريدون منكم الميل\nعن العدالة على أي وجه كان، إفراطا كان أو تفريطا.\nوكل ذلك ضلال، ولهذا وصى الله تعالى بقوله: ﴿وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ﴾⟪6:153⟫."}, {"a": [28], "v": 3, "p": 1198, "ev": 3, "ep": 1201, "sid": 1399, "t": "قوله تعالى: (يريد الله أن يخفف عنكم وخلق الإنسان ضعيفا (28)\n⟦3:1199⟧\nقوله: ﴿يُرِيدُ ٱللَّهُ﴾⟪4:28⟫ في موضع الحال، كأنه قال:\nوالله يريد أن يتوب عليكم، مريدا أن يخفف عنكم.\nوفي الآية أقوال: الأول: قول من خصصها وحملها على ما تقدم.\nوقال: عنى أنه أباح نكاح الأمة تخفيفا عنكم.\nفالإنسان ضعيف في تحيره عن \"إمساك نفسه عن مشتهاه.\nالثاني: أنه خفف عنكم تكلف النظر، وأزال الحيرة فيما بين لكم\nمما يجوز من النكاح.\nالثالث: أنه قصد به ما قال - صلى الله عليه وسلم -:\n\"جئتكم بالحنيفية السمحة\".\nوما ذكره في قوله تعالى: ﴿وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ﴾⟪7:157⟫.\nوالرابع: أنه تبين لكم مقصودكم وما دعيتم\n⟦3:1200⟧\nإليه من الثواب العظيم لتعرفوه، فيخف عليكم الصبر في تحريه.\nفالإنسان لا يمكنه الصبر فيما لا يعرف ثمرة الصبر فيه، ولهذا\nقال: ﴿وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرٗا﴾⟪18:68⟫.\nالخامس: يريد الله أن يخفف عنكم بما يحملكم من التعب.\nفإن كل تعب يفضي إلى راحة عظيمة، فذلك في الحقيقة راحة.\nولهذا قيل للرجل يتحمل تعبا عظيما في عبادة: ألا تريح نفسك؟\nفقال: راحتها أريد.\nالسادس: إنه لم يعن بالتخفيف ما يستخفه الطبع وتميل إليه\nالنفس، وإنما عنى ما يخف به تحمل ما يبلغنا إلى ثوابه، وعلى نحو\nهذه الآية قوله: ﴿يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ﴾⟪2:185⟫\nوقوله: ﴿وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ﴾⟪22:78⟫.\nووصف الإنسان بأنه خلق ضعيفا إنما هو باعتباره بالملأ الأعلى نحو:\n⟦3:1201⟧\n﴿ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ﴾⟪79:27⟫ أو باعتباره بنفسه دون ما يقويه من\nفيض الله ومعونته، أو اعتبارا بكثرة حاجاته، وافتقار بعضهم إلى\nبعض، أو اعتبارا بمبدئه ومنتهاه، كما قال تعالى: ﴿ٱللَّهُ ٱلَّذِي خَلَقَكُم مِّن ضَعۡفٖ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفٖ قُوَّةٗ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةٖ ضَعۡفٗا وَشَيۡبَةٗۚ﴾⟪30:54⟫\nفأما إذا اعتبر بعقله، وما أعطاه الله من القوة التي يتمكن بها\nمن خلافة الله في أرضه، ويتبلغ بها في الآخرة إلى\nجواره تعالى - فهو أقوى ما في هذا العالم.\nولهذا قال تعالى: ﴿وَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا﴾⟪17:70⟫."}, {"a": [29], "v": 3, "p": 1201, "ev": 3, "ep": 1206, "sid": 1402, "t": "قوله تعالى: (يا أيها الذين آمنوا لا تأكلوا أموالكم بينكم بالباطل إلا أن تكون تجارة عن تراض منكم ولا تقتلوا أنفسكم إن الله كان بكم رحيما (29)\nروي أنه لما نزلت هذه الآية امتنع بعضهم من أن يأكل عند غيره.\nحتى نزل قوله:\n⟦3:1202⟧\n﴿وَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ﴾⟪24:61⟫ إلى آخر الآية.\nولم يكن نسخا لكن تبيينا.\nوقوله: (بالباطل) إشارة إلى الوجوه التي حظر تناول المال منها ووضعه فيها، واستثنى التجارة تنبيها على إباحة الكسب إذا كان من وجهه.\nفمن نظر نظرا فقهيا قال: ظاهرها يقتضي أن لا يجوز تناول الغير منها، كالصلاة والزكاة والميراث وغير ذلك.\nوقال بعضهم: لم يعن بالتجارة المبايعة فقط.\nبل عنى كل معاملة مباحة من قرض وفرض، كما قال - صلى الله عليه وسلم -:\n\"لا يحل مال امرى مسلم إلا بطيب نفس منه \"،\n⟦3:1203⟧\nومنهم من عنى بذلك المنع من وضع المال وإنفاقه في غير الوجه المباح.\nوقال: عنى بالتجارة الوجهة المباحة التي يحل صرف المال إليها.\nوأما من نظر نظرا أدق من ذلك، فإنه جعل أكل المال بالباطل تناوله\nمن حيث لا يسوغه العقل، ولا يجوزه الشرع، من استنزال الناس\nعما في أيديهم بالخدع، ومساعدتهم على الباطل طمعا في نفع.\nوجعل من ذلك أيضا وضعه حيث لا يجوز، وإنفاقه رياء كما قال\nتعالى: ﴿لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ﴾⟪2:264⟫، وجعل هذه التجارة هي التجارة المذكورة بقوله تعالى:\n﴿هَلۡ أَدُلُّكُمۡ عَلَىٰ تِجَٰرَةٖ تُنجِيكُم مِّنۡ عَذَابٍ أَلِيمٖ﴾⟪61:10⟫ الآية.\nوفي قوله: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾⟪9:111⟫\nالآية.\n⟦3:1204⟧\nوشرط فيها التراضي، تنبيها أنه يحمد ذلك متى أنفق\nالإنسان في سبيل الله عن طيب نفس على الوجه الذي ينبغي وبمقدار\nما ينبغي، حسب ما بينه الله تعالى، ودل على رضاه في صرفه إليه.\nوقوله: ﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ﴾⟪4:29⟫ نظر إليه نظرات مختلفة.\nففسر بحسبها، الأول: لا يقتل بعضكم بعضا.\nقال: والنهي لا يصح إلا على هذا.\nفإن الإنسان مضطر إلى أن لا يقتل نفسه ما لم تعرض له شبهة\nكشبهة أهل الهند في قتلهم أنفسهم.\nقال: واستعار لفظ الخطاب في قوله (أنفسكم) تنبيها أنه يجب أن\nتكون نفس كل واحد منكم عند صاحبه كنفسه، قال: وعلى\n⟦3:1205⟧\nذلك نبه بقوله: ﴿مَّا خَلۡقُكُمۡ وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡسٖ وَٰحِدَةٍۚ﴾⟪31:28⟫.\nقال: وعلى هذا قال: ﴿فَإِذَا دَخَلۡتُم بُيُوتٗا فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ﴾⟪24:61⟫.\nالثاني: من حمل الخطاب على ذلك لكن خصص، وقال: لا يأكل\nبعضكم مال بعض، الذي به قوامه، فيكون فيه قتله.\nالثالث: لا يقتل بعضكم بعضا فيقتص منه فيكون كمن قتل نفسه.\nالرابع: لا تقتلوا أنفسكم بضجر وغضب.\nالخامس: لا تركبوا ما يؤدي بكم إلى القتل.\nفتكونوا قد قتلتم أنفسكم.\nوهذا كالرابع إلا أن مأخذه أعم منه.\nالسادس: قول من نظر نظرا أشرف فقال:\nلا تفعلوا ما يؤدي بكم إلى هلاك الأبد، فتكونوا قد قتلتم أنفسكم.\nوذلك بتصريف النفس في غير ما خلقت له، وبين للناس من\n⟦3:1206⟧\nالعلم والعمل الصالح المدلول عليه بقوله تعالى: ﴿وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ﴾⟪51:56⟫\nولذلك سمى من صرف نفسه في غير ذلك خاسرا.\nحيث قال: ﴿إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ﴾ الآية.\nقال: وقتل النفس في الحقيقة ترفيهها في الدنيا.\nوباعتبار الدنيا والآخرة أمر الإنسان تارة بقتل نفسه أي\nقمعها وتذليلها، ونهي تارة عن قتلها، ومثل هذه الآية قوله\nتعالى: ﴿وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ لَا تَسۡفِكُونَ دِمَآءَكُمۡ﴾⟪2:84⟫\nويجري مجراها في احتمال النظرين قوله: ﴿وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ﴾⟪2:195⟫."}, {"a": [30], "v": 3, "p": 1206, "ev": 3, "ep": 1208, "sid": 1407, "t": "قوله تعالى: (ومن يفعل ذلك عدوانا وظلما فسوف نصليه نارا وكان ذلك على الله يسيرا (30)\nالعدوان تجاوز العدالة بإفراط، وذلك أن العدل هو الوسط الذي تجاوزه الإفراط والقصور عنه جميعا، فمن حاد عنه قيل: جار، ومن بالغ في\n⟦3:1207⟧\nالجور قيل: طغى، ومن تخطاه بإفراط قيل: تعدى، وقيل لجميع\nذلك: الظلم، فالظلم أعم الأسماء.\nإن قيل: كيف جمع بين الظلم والعدوان، وقدم العدوان مع كونه أخص من الظلم، وحكم العام والخاص إذا اجتمعا أن يقدم العام على الخاص.\nنحو قوله: ﴿مَن كَانَ عَدُوّٗا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبۡرِيلَ وَمِيكَىٰلَ﴾⟪2:98⟫؟\nقيل: في ذلك جوابان:\nالأول: أن يكون العدوان إشارة إلى الظلم الذي يتجاوزه الإنسان إلى غيره، وعنى بالظلم ظلم النفس المعني في قوله: ﴿ظَّلَمُوٓاْ أَنفُسَهُمۡ﴾\nوهو الإثم المذكور في قوله تعالى: ﴿وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ﴾⟪5:2⟫\nفبين أن من جمع بين الأمرين فقد ظلم نفسه، وظلم غيره، فهو مستوجب للنار ، على هذا يكون العني بالظلم غير المعني بالعدوان.\nالثاني: أنه قدم العدوان الذي هو أخص من الظلم تنبيها أن من ارتكب صغيرة ولم يقمع نفسه عنها جرته إلى ما هو أعظم منها، فنبه أن حق\n⟦3:1208⟧\nالإنسان أن يحفظ نفسه عن الصغيرة خشية أن يقع فيما هو أعظم\nمنها، ومعنى الآية أن من يفعل ما نهي عنه من قتل النفس وأكل\nالمال بالباطل وسائر ما تقدم النهي عنه فسوف يجعله صلا كما\nقال: ﴿وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ﴾.\nونبه بقوله ﴿وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا﴾⟪4:30⟫\nأنه لا يتعذر عليه عقابهم."}, {"a": [31], "v": 3, "p": 1208, "ev": 3, "ep": 1214, "sid": 1409, "t": "قوله تعالى: (إن تجتنبوا كبائر ما تنهون عنه نكفر عنكم سيئاتكم وندخلكم مدخلا كريما (31)\nمن المفسرين - وهو أكثرهم - من حمل السيئات على الصغائر.\nوقال: معنى الآية: إن تجتنبوا كبائر الذنوب نكفر عنكم صغائرها.\nثم اختلفوا على أي وجه اعتبار الصغيرة والكبيرة.\nوذاك أن الصغير والكبير من الأسماء المتضايفة التي\nلا يعرف أحدهما إلا باعتبار الآخر،\n⟦3:1209⟧\nوقال بعضهم: في الذنوب كبيرة لا أكبر منها كالشرك، وصغيرة\nلا أصغر منها كحديث النفس أو همه بسيئة ونحو ذلك.\nوبينهما وسائط كل واحد بالإضافة إلى ما فوقه صغير، وبالإضافة إلى\nما دونه كبير، وقال: ومعنى الآية أن من عن له أمران فيهما\nمأثم، واضطر إلى ارتكاب أحدهما فارتكب أصغرهما وترك أكبرهما:\nكمن أكره على أن يقتل مسلما، أو يشرب قدح خمر فارتكب\nأصغرهما كفر عنه ما ارتكبه.\nوقال بعضهم: الذنوب كلها ضربان:\nضرب: كبيرة كالشرك، وقتل النفس بغير حق، والزنا.\nوضرب: صغيرة، وهؤلاء اختلفوا فمنهم من قال: الصغيرة\nغير معلومة، وهي كل ما علق به وعيد في\n⟦3:1210⟧\nالآخرة، أو جعل له عقوبة في الدنيا، وبعضها غير معلوم.\nقالوا: والصغائر كلها يجب أن تكون غير معلومة، وإلا كان\nإغراء بالمعصية، وذلك أن الله تعالى وعد أن يغفر بتجنب الكبائر\nالصغائر، فلو بينا جميعا لكان المكلف لا يبالي بارتكاب الصغائر\nمع تجنب الكبائر، فكان يؤدي ذلك إلى مفسدة، ومنهم من\nقال: يجب أن يكونا معلومين، وإلا لم يصح أن تكون الكبيرة\nمعلومة من حيث ما هي كبيرة لما تقدم أن ذلك من الأسماء\nالمتضايفة، التي لا يعرف أحدهما إلا بالآخر، قال: فالكبائر هي\n⟦3:1211⟧\nمحارم الله التي علم كونها محجورة، والصغائر ما هو متشكك فيه\nالمعني بقوله: \"دع مما يريبك إلى ما لا يريبك \".\nوعليه) دل النبي - صلى الله عليه وسلم - بقوله:\n\"الحلال بين والحرام بين، وبين ذلك أمور مشتبهات.\nوسأضرب لكم مثلا: إن الله حمى حمى، وإن حمى الله محارمه.\nومن رتع حول الحمى أوشك أن يقع فيه \".\nفمرتكب الكبائر\n⟦3:1212⟧\nجار مجرى داخل الحمى، ومرتكب الصغائر جار مجرى حوله.\nوالإنسان منهي عن الدنو منه، ومن لا يعرف ذلك فهو معرض\nالوقوع فيه، ثم كما قد بين تعالى في كتابه أن يغتفر الصغائر بشرط\nاجتناب الكبائر، فقد بين - صلى الله عليه وسلم - أن الصغيرة إنما تكون صغيرة ما لم يكن عليها إصرار. فقال:\n\"لا صغيرة مع إصرار\".\nوقال: \"إن المحرمات تجتمع على الرجل فتهلكه\".\nوإذا كانت الصغيرة منهيا عنها محذرا منها فلا ضير بتعريفها.\nبل يجب تعريفها، فالإنسان بتجنب الكبيرة يصير مطيعا غير فاسق.\nوبتجنب الصغيرة وهي المتشكك فيها يصير ورعا، ولذلك قيل لبعض الصحابة: ما أشد الورع؟\nفقال: ما أيسر الورع، إذا شككت في شيء فدعه،\n⟦3:1213⟧\nوقال بعض الصوفية: اعتبار الصغيرة والكبيرة بمرتكب الذنب.\nفقد يكون الذنب من زيد صغيرا ومن عمرو كبيرا، وذلك بحسب\nمراتبهم في المعارف والأحوال، فالأولياء الذين بلغوا المنازل\nقد يستعظم منهم ما لا يستعظم ممن لم يترشح لمنزلتهم، وذلك\nمعروف في السياسة الدنيوية، قال: ولهذا عاتب الله تعالى نبيه\nفي كثير من خطراته التي قد تجاوز بها عن غيره.\nوقال بعض المفسرين: معنى الآية: إن تجتنبوا هذه الكبائر التي\nنهيتم عنها في الآيات المتقدمة كفرنا عنكم ما قد أسأتم فيه من\n⟦3:1214⟧\nقبل، والمدخل الكريم: ما وعد به من الثواب العظيم، وأشار\nبه إلى جميع منازله على اختلاف مراتبها، ونبه أن كل مدخل\nلا يخرج عن كونه كريما أي مكرما."}, {"a": [32], "v": 3, "p": 1214, "ev": 3, "ep": 1217, "sid": 1415, "t": "قوله تعالى: (ولا تتمنوا ما فضل الله به بعضكم على بعض للرجال نصيب مما اكتسبوا وللنساء نصيب مما اكتسبن واسألوا الله من فضله إن الله كان بكل شيء عليما (32)\nالتمني: تشهي الإنسان أن يمنى له شيء، أي يقدر، وذلك مذموم.\nفإن تمنيه إن كان لشيء قدره أن لا يبلغ إلا بالطلب\nفيجب أن يطلبه لا أن يتشهاه، وإن كان لشيء يأتيه بغير طلب\nفتشهيه محال، وإن كان الشيء لم يقدر ففي تشهيه معارضة حكمة\n⟦3:1215⟧\nالله فيما قدر، ولذلك قيل: من تمنى فقد أساء الظن بالله.\nولكون ذلك غير مغن، قال الشاعر:\n. . . إن ليتا وإن لوا عناء\nوقال:\n. . . وما يغني عن الحدثان ليت\nوهو مع ذلك ذريعة إلى التحاسد والبخل والظلم.\nوقد روي في الآية أن أم سلمة قالت: ليتنا كنا رجالا فنجاهد،\n⟦3:1216⟧\nفأنزل الله تعالى ذلك، وقوله: ﴿لِّلرِّجَالِ نَصِيبٞ﴾⟪4:32⟫\nقيل: إنها قالت: ليتنا لم يجعل ثوابنا في الآخرة على نصف ثواب الرجل.\nكما جعل نصيبنا من الميراث، فأنزل الله تعالى تنبيها على أن\nلا اعتبار في مجازاة الأعمال بالذكورية والأنوثية.\nوقيل: هو تبيين لفضل الرجال كقوله: ﴿وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ﴾⟪2:228⟫.\nوقيل: هو تبيين أن الحسد لا يغني، وأن الله لا يغير لحسد حاسد.\nوقيل: هو حث على طلب منزلة الحسود بالعمل الصالح دون الحسد والتمني، كما قال - صلى الله عليه وسلم -:\n\"ليس الإيمان بالتمني ولا بالتحلي \"\nوقال محمد بن بحر: معناه ليس كل ما للميت واجبا للورثة.\nبل له نصيب يوصي به.\nقال: وذلك نحو ما ذكر الله تعالى في قوله:\n⟦3:1217⟧\n﴿كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ﴾⟪2:180⟫.\nوبين بقوله: ﴿إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا﴾⟪4:32⟫ أنه أعلم\nبما يستحق كل إنسان، كقوله تعالى: ﴿ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ﴾⟪6:124⟫."}];
